(function(){const d=window.L4_TEST_DATA;if(!d||d.revision!=="2026-11-12-tests-2"||d.tests.length!==20)throw Error("Revised test pack order incomplete");d.tests.push(...[{"id":"T21","title":"K11 · Organisational Analysis Tools & Methods","description":"Organisational tools, analytical capability, support and trade-offs.","questions":[{"ksb":"K11","objective":"Data volume","prompt":"An export is approaching the spreadsheet tool's practical limits. Which method-selection considerations are relevant?","options":[{"text":"Choose based only on a tiny demonstration file","why":"A small sample may not expose the limitations of the actual workload.","correct":false,"id":"A"},{"text":"Assess processing scale and responsiveness with representative data","why":"A small sample may not expose the limitations of the actual workload.","correct":true,"id":"B"},{"text":"Split files randomly and assume totals will remain straightforward","why":"Arbitrary partitioning and export success do not establish a reliable end-to-end workflow.","correct":false,"id":"C"},{"text":"Export every detail repeatedly before checking what the report needs","why":"Appropriate source-side work can reduce unnecessary transfer and local processing.","correct":false,"id":"D"},{"text":"Assume database processing is available simply because SQL exists","why":"A method needs authorised access and suitable infrastructure to be usable.","correct":false,"id":"E"},{"text":"Check the team's permissions and infrastructure","why":"A method needs authorised access and suitable infrastructure to be usable.","correct":true,"id":"F"},{"text":"Treat a successful export as proof the entire analysis is scalable","why":"Arbitrary partitioning and export success do not establish a reliable end-to-end workflow.","correct":false,"id":"G"},{"text":"Consider pushing suitable aggregation to the database","why":"Appropriate source-side work can reduce unnecessary transfer and local processing.","correct":true,"id":"H"}],"answer":"A small sample may not expose the limitations of the actual workload. Appropriate source-side work can reduce unnecessary transfer and local processing. A method needs authorised access and suitable infrastructure to be usable. Arbitrary partitioning and export success do not establish a reliable end-to-end workflow.","source":{"anchor":"ksb-k11","guideSha256":"bc1a99c3c235c6421238572df4d834ea21e8a317a4c5f38e689e95adc86b5d96","excerpt":"Describe tools your organisation actually makes available, then compare them against the analytical requirement."},"id":"T21-E2-Q01"},{"ksb":"K11","objective":"Recurring extraction","prompt":"A report repeats the same joins and checks each week. The approved options include SQL and manual spreadsheet copying. Which trade-offs favour a repeatable query?","options":[{"text":"Automation removes the need for output reconciliation","why":"Automated extraction still requires relevant quality checks.","correct":false,"id":"A"},{"text":"Counts and exceptions can be checked systematically","why":"Automated extraction still requires relevant quality checks.","correct":true,"id":"B"},{"text":"Consider whether the team can support the query","why":"Ongoing support and capability affect the practical cost of the choice.","correct":true,"id":"C"},{"text":"Query version history is equivalent to proof every result is correct","why":"Reviewable changes support traceability without guaranteeing analytical correctness.","correct":false,"id":"D"},{"text":"Versioned query changes can be reviewed","why":"Reviewable changes support traceability without guaranteeing analytical correctness.","correct":true,"id":"E"},{"text":"A saved query guarantees source keys will never change","why":"Repeatability improves consistency but still needs monitoring and maintenance.","correct":false,"id":"F"},{"text":"Ignore team skills because code is always cheaper","why":"Ongoing support and capability affect the practical cost of the choice.","correct":false,"id":"G"},{"text":"The matching logic can be recorded and rerun consistently","why":"Repeatability improves consistency but still needs monitoring and maintenance.","correct":true,"id":"H"}],"answer":"Repeatability improves consistency but still needs monitoring and maintenance. Automated extraction still requires relevant quality checks. Reviewable changes support traceability without guaranteeing analytical correctness. Ongoing support and capability affect the practical cost of the choice.","source":{"anchor":"ksb-k11","guideSha256":"bc1a99c3c235c6421238572df4d834ea21e8a317a4c5f38e689e95adc86b5d96","excerpt":"Describe tools your organisation actually makes available, then compare them against the analytical requirement."},"id":"T21-E2-Q02"},{"ksb":"K11","objective":"Support risk","prompt":"A complex report relies on one analyst's undocumented code. The output is accurate today, but the analyst is leaving. Which evaluation is balanced?","options":[{"text":"Assess feasible support or simplification options","why":"An improvement needs to preserve required capability and account for transition cost.","correct":true,"id":"A"},{"text":"Identify responsibility for ongoing checks","why":"Someone still needs to monitor failures, changes and output quality.","correct":true,"id":"B"},{"text":"Explain the cost and benefit of a realistic alternative","why":"A support concern warrants evaluating documentation, handover and alternatives; familiarity alone does not establish a suitable replacement or justify its migration cost.","correct":true,"id":"C"},{"text":"Treat present accuracy as proof of maintainability","why":"Correct current output does not establish that another person can operate or change the workflow.","correct":false,"id":"D"},{"text":"Replace the code immediately with a familiar spreadsheet before assessing scale and recurring workload","why":"A support concern warrants evaluating documentation, handover and alternatives; familiarity alone does not establish a suitable replacement or justify its migration cost.","correct":false,"id":"E"},{"text":"Replace the system immediately without checking business requirements","why":"An improvement needs to preserve required capability and account for transition cost.","correct":false,"id":"F"},{"text":"Assume automated execution eliminates ownership","why":"Someone still needs to monitor failures, changes and output quality.","correct":false,"id":"G"},{"text":"Consider documentation and knowledge transfer","why":"Correct current output does not establish that another person can operate or change the workflow.","correct":true,"id":"H"}],"answer":"Correct current output does not establish that another person can operate or change the workflow. An improvement needs to preserve required capability and account for transition cost. A support concern warrants evaluating documentation, handover and alternatives; familiarity alone does not establish a suitable replacement or justify its migration cost. Someone still needs to monitor failures, changes and output quality.","source":{"anchor":"ksb-k11","guideSha256":"bc1a99c3c235c6421238572df4d834ea21e8a317a4c5f38e689e95adc86b5d96","excerpt":"Describe tools your organisation actually makes available, then compare them against the analytical requirement."},"id":"T21-E2-Q03"},{"ksb":"K11","objective":"Approved capabilities","prompt":"A new analyst must select tools for a confidential reporting task. Which information should establish the available options?","options":[{"text":"Identify the methods the task actually needs","why":"Relevant analytical requirements should guide the comparison.","correct":true,"id":"A"},{"text":"Check the organisation's approved tools and permitted uses","why":"Course examples do not establish the organisation's permissions or deployment arrangements.","correct":true,"id":"B"},{"text":"Infer permission solely from a vendor's security advertisement","why":"Licensing and marketing do not replace organisational approval for the intended data use.","correct":false,"id":"C"},{"text":"Treat every tool mentioned in the course as approved locally","why":"Course examples do not establish the organisation's permissions or deployment arrangements.","correct":false,"id":"D"},{"text":"Choose a tool only because colleagues use it for unrelated work","why":"Relevant analytical requirements should guide the comparison.","correct":false,"id":"E"},{"text":"Assume an installed application can connect to every database","why":"Installation and usable authorised connectivity are separate requirements.","correct":false,"id":"F"},{"text":"Treat a personal licence as approval for confidential processing","why":"Licensing and marketing do not replace organisational approval for the intended data use.","correct":false,"id":"G"},{"text":"Check access to the required sources","why":"Installation and usable authorised connectivity are separate requirements.","correct":true,"id":"H"}],"answer":"Course examples do not establish the organisation's permissions or deployment arrangements. Installation and usable authorised connectivity are separate requirements. Relevant analytical requirements should guide the comparison. Licensing and marketing do not replace organisational approval for the intended data use.","source":{"anchor":"ksb-k11","guideSha256":"bc1a99c3c235c6421238572df4d834ea21e8a317a4c5f38e689e95adc86b5d96","excerpt":"Describe tools your organisation actually makes available, then compare them against the analytical requirement."},"id":"T21-E2-Q04"},{"ksb":"K11","objective":"Visual tool choice","prompt":"A dashboard must be maintained by an existing Power BI team and distributed through its approved service. Which considerations are justified?","options":[{"text":"Existing support and distribution arrangements favour that workflow","why":"Operational fit is relevant, but required analytical capabilities still need checking.","correct":true,"id":"A"},{"text":"Treat the default template as evidence of accessibility","why":"Relevant accessibility needs require evaluation of the actual output.","correct":false,"id":"B"},{"text":"Ignore maintainability because the analyst can create the first version","why":"Novelty and initial creation do not address long-term ownership and use.","correct":false,"id":"C"},{"text":"Select a different tool solely for a novel visual effect","why":"Novelty and initial creation do not address long-term ownership and use.","correct":false,"id":"D"},{"text":"Assume the desktop preview proves production refresh will work","why":"Deployment can have different connector, gateway or licence constraints.","correct":false,"id":"E"},{"text":"Check connector, refresh and licensing requirements","why":"Deployment can have different connector, gateway or licence constraints.","correct":true,"id":"F"},{"text":"Evaluate accessibility and audience needs","why":"Relevant accessibility needs require evaluation of the actual output.","correct":true,"id":"G"},{"text":"Existing familiarity proves it can perform every required analysis","why":"Operational fit is relevant, but required analytical capabilities still need checking.","correct":false,"id":"H"}],"answer":"Operational fit is relevant, but required analytical capabilities still need checking. Deployment can have different connector, gateway or licence constraints. Relevant accessibility needs require evaluation of the actual output. Novelty and initial creation do not address long-term ownership and use.","source":{"anchor":"ksb-k11","guideSha256":"bc1a99c3c235c6421238572df4d834ea21e8a317a4c5f38e689e95adc86b5d96","excerpt":"Describe tools your organisation actually makes available, then compare them against the analytical requirement."},"id":"T21-E2-Q05"},{"ksb":"K11","objective":"Methods and tools","prompt":"A report describes only 'Excel, SQL and Power BI' when asked about analytical methods. Which additions improve the account?","options":[{"text":"Claim every named tool was used at every stage","why":"A specific division of roles is more informative and truthful.","correct":false,"id":"A"},{"text":"Explain relevant assumptions and validation","why":"Tool choice does not remove the assumptions behind calculations and comparisons.","correct":true,"id":"B"},{"text":"Link each tool to its role in the workflow","why":"A specific division of roles is more informative and truthful.","correct":true,"id":"C"},{"text":"Assume a commercial tool removes methodological assumptions","why":"Tool choice does not remove the assumptions behind calculations and comparisons.","correct":false,"id":"D"},{"text":"Describe a dashboard screenshot as a complete statistical method","why":"Querying and visual presentation do not by themselves establish predictive or inferential methods.","correct":false,"id":"E"},{"text":"Explain the transformations and comparisons performed","why":"Tools provide capabilities; methods describe what analytical work was done and why.","correct":true,"id":"F"},{"text":"Treat a list of product names as the complete method","why":"Tools provide capabilities; methods describe what analytical work was done and why.","correct":false,"id":"G"},{"text":"Describe SQL as necessarily predictive modelling","why":"Querying and visual presentation do not by themselves establish predictive or inferential methods.","correct":false,"id":"H"}],"answer":"Tools provide capabilities; methods describe what analytical work was done and why. A specific division of roles is more informative and truthful. Tool choice does not remove the assumptions behind calculations and comparisons. Querying and visual presentation do not by themselves establish predictive or inferential methods.","source":{"anchor":"ksb-k11","guideSha256":"bc1a99c3c235c6421238572df4d834ea21e8a317a4c5f38e689e95adc86b5d96","excerpt":"Describe tools your organisation actually makes available, then compare them against the analytical requirement."},"id":"T21-E2-Q06"},{"ksb":"K11","objective":"Reproducible code","prompt":"An analyst proposes Python because the cleaning has many repeated steps. Which evidence supports that choice?","options":[{"text":"Code that runs without exceptions establishes correct business logic","why":"Execution success does not establish semantic correctness.","correct":false,"id":"A"},{"text":"Explain the benefit over a realistic available alternative","why":"A useful comparison considers feasible alternatives and their actual trade-offs.","correct":true,"id":"B"},{"text":"Versioned code records the applied transformations","why":"Reproducibility depends on captured code, inputs, configuration and environment, not the language name.","correct":true,"id":"C"},{"text":"Using Python alone proves the analysis is reproducible","why":"Reproducibility depends on captured code, inputs, configuration and environment, not the language name.","correct":false,"id":"D"},{"text":"Checks validate the transformed output","why":"Execution success does not establish semantic correctness.","correct":true,"id":"E"},{"text":"Compare Python only with a tool the organisation cannot use","why":"A useful comparison considers feasible alternatives and their actual trade-offs.","correct":false,"id":"F"},{"text":"Leave package versions and required setup implicit","why":"Dependency information helps another person reproduce and maintain the workflow.","correct":false,"id":"G"},{"text":"Suitable dependencies and handover are documented","why":"Dependency information helps another person reproduce and maintain the workflow.","correct":true,"id":"H"}],"answer":"Reproducibility depends on captured code, inputs, configuration and environment, not the language name. Execution success does not establish semantic correctness. Dependency information helps another person reproduce and maintain the workflow. A useful comparison considers feasible alternatives and their actual trade-offs.","source":{"anchor":"ksb-k11","guideSha256":"bc1a99c3c235c6421238572df4d834ea21e8a317a4c5f38e689e95adc86b5d96","excerpt":"Describe tools your organisation actually makes available, then compare them against the analytical requirement."},"id":"T21-E2-Q07"},{"ksb":"K11","objective":"Evaluating outcome","prompt":"Two tools can produce the required result. Which comparison would best justify the final choice?","options":[{"text":"Compare actual analytical fit, security and team capability","why":"Local requirements are more relevant than popularity to the specific project outcome.","correct":true,"id":"A"},{"text":"Compare only the time needed to make the first chart","why":"Recurring operation can dominate the practical cost of the workflow.","correct":false,"id":"B"},{"text":"Treat the rejected option as unusable merely because it was not selected","why":"A contextual choice does not establish a universal ranking or invalidate every alternative.","correct":false,"id":"C"},{"text":"Explain measured or observed benefits and remaining limitations","why":"Benefits should be supported or clearly identified as estimates.","correct":true,"id":"D"},{"text":"Rank tools only by general online popularity","why":"Local requirements are more relevant than popularity to the specific project outcome.","correct":false,"id":"E"},{"text":"Assert the chosen tool is optimal for every future project","why":"A contextual choice does not establish a universal ranking or invalidate every alternative.","correct":false,"id":"F"},{"text":"Claim unmeasured time savings as exact verified figures","why":"Benefits should be supported or clearly identified as estimates.","correct":false,"id":"G"},{"text":"Include recurring effort and handover costs","why":"Recurring operation can dominate the practical cost of the workflow.","correct":true,"id":"H"}],"answer":"Local requirements are more relevant than popularity to the specific project outcome. Recurring operation can dominate the practical cost of the workflow. Benefits should be supported or clearly identified as estimates. A contextual choice does not establish a universal ranking or invalidate every alternative.","source":{"anchor":"ksb-k11","guideSha256":"bc1a99c3c235c6421238572df4d834ea21e8a317a4c5f38e689e95adc86b5d96","excerpt":"Describe tools your organisation actually makes available, then compare them against the analytical requirement."},"id":"T21-E2-Q08"},{"ksb":"K11","objective":"Licensed versus custom","prompt":"A licensed BI product supports managed distribution; a Python workflow offers custom modelling. Which comparison is sound?","options":[{"text":"Consider an approved combination if justified","why":"Different approved tools may appropriately serve different stages.","correct":true,"id":"A"},{"text":"Require the entire lifecycle to use one product regardless of limitations","why":"Different approved tools may appropriately serve different stages.","correct":false,"id":"B"},{"text":"Assume custom code carries no operational cost","why":"Code can require testing, hosting, support and knowledge transfer.","correct":false,"id":"C"},{"text":"Compare capabilities against the actual modelling and reporting requirements","why":"Direct licence price is only one part of the fit and cost.","correct":true,"id":"D"},{"text":"Choose solely by whether the software has a licence fee","why":"Direct licence price is only one part of the fit and cost.","correct":false,"id":"E"},{"text":"Consider support, deployment and maintenance for both options","why":"Code can require testing, hosting, support and knowledge transfer.","correct":true,"id":"F"},{"text":"Assume licensed software cannot support repeatable workflows","why":"Repeatability depends on the workflow and controls rather than the licensing category alone.","correct":false,"id":"G"},{"text":"Consider reproducibility and change control","why":"Repeatability depends on the workflow and controls rather than the licensing category alone.","correct":true,"id":"H"}],"answer":"Direct licence price is only one part of the fit and cost. Code can require testing, hosting, support and knowledge transfer. Repeatability depends on the workflow and controls rather than the licensing category alone. Different approved tools may appropriately serve different stages.","source":{"anchor":"ksb-k11","guideSha256":"bc1a99c3c235c6421238572df4d834ea21e8a317a4c5f38e689e95adc86b5d96","excerpt":"Describe tools your organisation actually makes available, then compare them against the analytical requirement."},"id":"T21-E2-Q09"},{"ksb":"K11","objective":"Small one-off task","prompt":"A small, authorised table needs a one-off summary for a colleague who uses Excel. Which reasoning is balanced?","options":[{"text":"Choose an unfamiliar format solely to demonstrate technical sophistication","why":"The delivered result should fit the audience and ongoing use.","correct":false,"id":"A"},{"text":"Consider handover and the colleague's ability to use the result","why":"The delivered result should fit the audience and ongoing use.","correct":true,"id":"B"},{"text":"A small table makes formula validation unnecessary","why":"Scale does not remove the possibility of a calculation or selection error.","correct":false,"id":"C"},{"text":"Infer reproducibility merely from a polished workbook","why":"A suitable choice for one task and attractive formatting do not establish universal fitness or documented reproducibility.","correct":false,"id":"D"},{"text":"Excel may be proportionate if it meets the analytical need","why":"The appropriate tool depends on the task rather than a universal preference for code.","correct":true,"id":"E"},{"text":"Record transformations and check the calculations","why":"Scale does not remove the possibility of a calculation or selection error.","correct":true,"id":"F"},{"text":"Treat familiarity as proof Excel meets every future requirement","why":"A suitable choice for one task and attractive formatting do not establish universal fitness or documented reproducibility.","correct":false,"id":"G"},{"text":"A scripted pipeline is mandatory for every small summary","why":"The appropriate tool depends on the task rather than a universal preference for code.","correct":false,"id":"H"}],"answer":"The appropriate tool depends on the task rather than a universal preference for code. Scale does not remove the possibility of a calculation or selection error. The delivered result should fit the audience and ongoing use. A suitable choice for one task and attractive formatting do not establish universal fitness or documented reproducibility.","source":{"anchor":"ksb-k11","guideSha256":"bc1a99c3c235c6421238572df4d834ea21e8a317a4c5f38e689e95adc86b5d96","excerpt":"Describe tools your organisation actually makes available, then compare them against the analytical requirement."},"id":"T21-E2-Q10"}]},{"id":"T22","title":"K12 · Organisational Data Architecture","description":"Actual architecture, data flow, governance and appropriate scale.","questions":[{"ksb":"K12","objective":"Identity and connectors","prompt":"A desktop tool connects successfully to a database, but the published dashboard cannot refresh through the service. Which architectural factors should be checked?","options":[{"text":"Assume the desktop user's permissions automatically transfer","why":"The published service may use a different identity and access context.","correct":false,"id":"A"},{"text":"Required gateways or network routes","why":"Managed connectivity depends on the actual network and gateway arrangement.","correct":true,"id":"B"},{"text":"Treat every refresh failure as evidence the underlying data is wrong","why":"Desktop and service refresh can use different identities, credentials and network paths; approved authentication and infrastructure need checking.","correct":false,"id":"C"},{"text":"Infer production support from the desktop preview alone","why":"Desktop and hosted environments can have different capabilities and configuration needs.","correct":false,"id":"D"},{"text":"Treat a successful desktop sign-in as confirmation that the refresh service has the same identity and permissions","why":"Desktop and service refresh can use different identities, credentials and network paths; approved authentication and infrastructure need checking.","correct":false,"id":"E"},{"text":"Assume publication places the database on the public internet","why":"Managed connectivity depends on the actual network and gateway arrangement.","correct":false,"id":"F"},{"text":"The service's identity and authorised access","why":"The published service may use a different identity and access context.","correct":true,"id":"G"},{"text":"Supported connector and refresh configuration","why":"Desktop and hosted environments can have different capabilities and configuration needs.","correct":true,"id":"H"}],"answer":"The published service may use a different identity and access context. Managed connectivity depends on the actual network and gateway arrangement. Desktop and hosted environments can have different capabilities and configuration needs. Desktop and service refresh can use different identities, credentials and network paths; approved authentication and infrastructure need checking.","source":{"anchor":"ksb-k12","guideSha256":"82a19528e64643915c69aafa73db1a3bcd08a4f6a7f6715d3baf0c435f7f4a97","excerpt":"Data architecture describes how sources, storage, transformation, governance and consumption fit together."},"id":"T22-E2-Q01"},{"ksb":"K12","objective":"Source-to-report flow","prompt":"An operational database feeds a warehouse nightly, and a dashboard reads the warehouse each morning. Which architecture description is accurate?","options":[{"text":"Identify each component and the direction of data movement","why":"The dashboard consumes a downstream analytical representation in this workflow.","correct":true,"id":"A"},{"text":"Describe the dashboard as the original record-keeping system","why":"The dashboard consumes a downstream analytical representation in this workflow.","correct":false,"id":"B"},{"text":"Call the entire architecture simply 'the cloud'","why":"A useful architecture account identifies actual component roles and relationships. Supplying reports does not establish responsibility for operational transactions.","correct":false,"id":"C"},{"text":"Explain both the nightly load and dashboard refresh","why":"The warehouse load limits which source changes the morning report can contain.","correct":true,"id":"D"},{"text":"Identify ownership and access at relevant stages","why":"Permissions can differ between the source, warehouse and reporting layer.","correct":true,"id":"E"},{"text":"Treat one successful dashboard login as access to all source systems","why":"Permissions can differ between the source, warehouse and reporting layer.","correct":false,"id":"F"},{"text":"State that morning dashboard refresh guarantees current source transactions","why":"The warehouse load limits which source changes the morning report can contain.","correct":false,"id":"G"},{"text":"Describe the warehouse as the operational write-back system because it supplies the dashboard","why":"A useful architecture account identifies actual component roles and relationships. Supplying reports does not establish responsibility for operational transactions.","correct":false,"id":"H"}],"answer":"The dashboard consumes a downstream analytical representation in this workflow. The warehouse load limits which source changes the morning report can contain. Permissions can differ between the source, warehouse and reporting layer. A useful architecture account identifies actual component roles and relationships. Supplying reports does not establish responsibility for operational transactions.","source":{"anchor":"ksb-k12","guideSha256":"82a19528e64643915c69aafa73db1a3bcd08a4f6a7f6715d3baf0c435f7f4a97","excerpt":"Data architecture describes how sources, storage, transformation, governance and consumption fit together."},"id":"T22-E2-Q02"},{"ksb":"K12","objective":"Centralised storage","prompt":"The organisation requires analytical extracts to remain in a managed workspace. Which architecture implications follow?","options":[{"text":"Use approved interfaces and storage locations","why":"Centralisation does not remove restrictions on extraction or local copies.","correct":true,"id":"A"},{"text":"Select a tool before checking whether it can reach the managed source","why":"Connectivity constraints affect whether a tool can operate in the architecture.","correct":false,"id":"B"},{"text":"Explain the access roles relevant to the project","why":"Access can depend on role, purpose and data sensitivity.","correct":true,"id":"C"},{"text":"Plan tools around available authorised connections","why":"Connectivity constraints affect whether a tool can operate in the architecture.","correct":true,"id":"D"},{"text":"Assume all analysts inherit identical permissions","why":"Access can depend on role, purpose and data sensitivity.","correct":false,"id":"E"},{"text":"Account for retention and backup arrangements","why":"Managed infrastructure still operates within organisational storage and retention responsibilities.","correct":true,"id":"F"},{"text":"Treat central storage as permission to download every record personally","why":"Centralisation does not remove restrictions on extraction or local copies.","correct":false,"id":"G"},{"text":"Assume the provider's infrastructure removes all retention decisions","why":"Managed infrastructure still operates within organisational storage and retention responsibilities.","correct":false,"id":"H"}],"answer":"Centralisation does not remove restrictions on extraction or local copies. Access can depend on role, purpose and data sensitivity. Managed infrastructure still operates within organisational storage and retention responsibilities. Connectivity constraints affect whether a tool can operate in the architecture.","source":{"anchor":"ksb-k12","guideSha256":"82a19528e64643915c69aafa73db1a3bcd08a4f6a7f6715d3baf0c435f7f4a97","excerpt":"Data architecture describes how sources, storage, transformation, governance and consumption fit together."},"id":"T22-E2-Q03"},{"ksb":"K12","objective":"Lineage","prompt":"A measure differs from its operational-system total. Which architecture information helps investigate the difference?","options":[{"text":"Check refresh times and extraction scope at each stage","why":"Connected layers can still differ in timing and included records.","correct":true,"id":"A"},{"text":"Trace the source, transformations and aggregation stages","why":"Lineage traces where records or meanings change; aggregate agreement can hide offsetting omissions, duplicates or mapping errors.","correct":true,"id":"B"},{"text":"Use a matching grand total as sufficient evidence that every source-to-report mapping is correct","why":"Lineage traces where records or meanings change; aggregate agreement can hide offsetting omissions, duplicates or mapping errors.","correct":false,"id":"C"},{"text":"Replace the final measure until it matches an expected headline","why":"Intermediate checks investigate the cause rather than forcing a result.","correct":false,"id":"D"},{"text":"Identify responsible owners for the affected transformations","why":"Ownership should follow the component responsible for the relevant behaviour.","correct":true,"id":"E"},{"text":"Reconcile values at suitable intermediate points","why":"Intermediate checks investigate the cause rather than forcing a result.","correct":true,"id":"F"},{"text":"Send the issue only to whoever last opened the dashboard","why":"Ownership should follow the component responsible for the relevant behaviour.","correct":false,"id":"G"},{"text":"Assume all layers represent the same time simply because they are linked","why":"Connected layers can still differ in timing and included records.","correct":false,"id":"H"}],"answer":"Lineage traces where records or meanings change; aggregate agreement can hide offsetting omissions, duplicates or mapping errors. Connected layers can still differ in timing and included records. Ownership should follow the component responsible for the relevant behaviour. Intermediate checks investigate the cause rather than forcing a result.","source":{"anchor":"ksb-k12","guideSha256":"82a19528e64643915c69aafa73db1a3bcd08a4f6a7f6715d3baf0c435f7f4a97","excerpt":"Data architecture describes how sources, storage, transformation, governance and consumption fit together."},"id":"T22-E2-Q04"},{"ksb":"K12","objective":"Tool constraints","prompt":"A policy permits querying a warehouse through approved read-only connections. An analyst wants a local tool requiring unrestricted write access. Which decisions are appropriate?","options":[{"text":"Bypass the warehouse controls with an unofficial export","why":"Constraints should be resolved through approved routes rather than evaded.","correct":false,"id":"A"},{"text":"Claim the tool was used successfully without connecting it","why":"Infrastructure limits and actual tool use need accurate, distinct descriptions.","correct":false,"id":"B"},{"text":"Assume an analytical requirement grants write access","why":"A business question does not itself authorise wider platform privileges.","correct":false,"id":"C"},{"text":"Raise an unmet capability through the responsible process","why":"Constraints should be resolved through approved routes rather than evaded.","correct":true,"id":"D"},{"text":"Select solely by the analyst's preferred interface","why":"A usable choice must fit the available authorised infrastructure.","correct":false,"id":"E"},{"text":"Treat every connector limitation as a defect in the data","why":"Infrastructure limits and actual tool use need accurate, distinct descriptions.","correct":false,"id":"F"},{"text":"Assess whether a supported read-only workflow meets the task","why":"A business question does not itself authorise wider platform privileges.","correct":true,"id":"G"},{"text":"Compare approved tools compatible with the architecture","why":"A usable choice must fit the available authorised infrastructure.","correct":true,"id":"H"}],"answer":"A business question does not itself authorise wider platform privileges. A usable choice must fit the available authorised infrastructure. Constraints should be resolved through approved routes rather than evaded. Infrastructure limits and actual tool use need accurate, distinct descriptions.","source":{"anchor":"ksb-k12","guideSha256":"82a19528e64643915c69aafa73db1a3bcd08a4f6a7f6715d3baf0c435f7f4a97","excerpt":"Data architecture describes how sources, storage, transformation, governance and consumption fit together."},"id":"T22-E2-Q05"},{"ksb":"K12","objective":"Backup and continuity","prompt":"The platform team runs backups, but no one has confirmed restoration requirements for a critical recurring report. Which architecture questions matter?","options":[{"text":"Assume restoring one table always restores the complete workflow","why":"Data, configuration, identities and downstream components can all affect recovery.","correct":false,"id":"A"},{"text":"Set the acceptable recovery time equal to the interval between backups","why":"Backup frequency concerns the potential data-loss window; acceptable restoration time needs its own operational agreement.","correct":false,"id":"B"},{"text":"Respect the approved backup and retention process","why":"Continuity should work within authorised storage and recovery arrangements.","correct":true,"id":"C"},{"text":"Identify dependencies needed to resume the report","why":"Data, configuration, identities and downstream components can all affect recovery.","correct":true,"id":"D"},{"text":"Clarify recovery objectives and responsibilities","why":"Backup frequency concerns the potential data-loss window; acceptable restoration time needs its own operational agreement.","correct":true,"id":"E"},{"text":"Create uncontrolled personal copies as the default continuity plan","why":"Continuity should work within authorised storage and recovery arrangements.","correct":false,"id":"F"},{"text":"Treat file existence as proof a usable restore is possible","why":"A stored backup alone does not demonstrate successful recovery.","correct":false,"id":"G"},{"text":"Establish how restore capability is checked","why":"A stored backup alone does not demonstrate successful recovery.","correct":true,"id":"H"}],"answer":"Backup frequency concerns the potential data-loss window; acceptable restoration time needs its own operational agreement. A stored backup alone does not demonstrate successful recovery. Data, configuration, identities and downstream components can all affect recovery. Continuity should work within authorised storage and recovery arrangements.","source":{"anchor":"ksb-k12","guideSha256":"82a19528e64643915c69aafa73db1a3bcd08a4f6a7f6715d3baf0c435f7f4a97","excerpt":"Data architecture describes how sources, storage, transformation, governance and consumption fit together."},"id":"T22-E2-Q06"},{"ksb":"K12","objective":"Warehouse versus lake","prompt":"A platform uses a lake for varied source objects and a warehouse for curated reporting tables. Which explanation preserves the distinction?","options":[{"text":"Explain the transformations between the two layers","why":"Their roles and transformations matter to understanding the actual data flow.","correct":true,"id":"A"},{"text":"The warehouse supports defined analytical structures","why":"The stated warehouse role concerns curated analytical use rather than only operational recording.","correct":true,"id":"B"},{"text":"The lake can retain varied formats with appropriate governance","why":"Variety increases the importance of discoverability, ownership and meaning.","correct":true,"id":"C"},{"text":"Infer that lake data is public because it is raw","why":"Raw status does not establish access rights, and curation does not make further quality assessment unnecessary.","correct":false,"id":"D"},{"text":"The lake's varied formats imply no metadata is needed","why":"Variety increases the importance of discoverability, ownership and meaning.","correct":false,"id":"E"},{"text":"Treat the lake and warehouse names as interchangeable","why":"Their roles and transformations matter to understanding the actual data flow.","correct":false,"id":"F"},{"text":"Every warehouse table is necessarily an operational transaction log","why":"The stated warehouse role concerns curated analytical use rather than only operational recording.","correct":false,"id":"G"},{"text":"Infer that warehouse data needs no quality checks because it is curated","why":"Raw status does not establish access rights, and curation does not make further quality assessment unnecessary.","correct":false,"id":"H"}],"answer":"Variety increases the importance of discoverability, ownership and meaning. The stated warehouse role concerns curated analytical use rather than only operational recording. Their roles and transformations matter to understanding the actual data flow. Raw status does not establish access rights, and curation does not make further quality assessment unnecessary.","source":{"anchor":"ksb-k12","guideSha256":"82a19528e64643915c69aafa73db1a3bcd08a4f6a7f6715d3baf0c435f7f4a97","excerpt":"Data architecture describes how sources, storage, transformation, governance and consumption fit together."},"id":"T22-E2-Q07"},{"ksb":"K12","objective":"Big-data justification","prompt":"A modest, stable dataset fits the organisation's existing relational platform. A proposal recommends distributed processing solely because it is fashionable. Which evaluation is justified?","options":[{"text":"Claim distributed processing is unsuitable for every analytical task","why":"Rejecting an unnecessary component does not justify a universal claim against its category or another platform's capabilities.","correct":false,"id":"A"},{"text":"Explain why the existing platform may be sufficient","why":"A truthful account should describe the infrastructure actually used and needed.","correct":true,"id":"B"},{"text":"Treat any spreadsheet import as proof of a big-data requirement","why":"The architecture should fit actual workload characteristics rather than a label.","correct":false,"id":"C"},{"text":"Assess actual volume, speed and variety needs","why":"The architecture should fit actual workload characteristics rather than a label.","correct":true,"id":"D"},{"text":"Invent use of a data lake to make the project sound advanced","why":"A truthful account should describe the infrastructure actually used and needed.","correct":false,"id":"E"},{"text":"Compare operational complexity and team support","why":"Additional infrastructure can add cost and maintenance without a relevant benefit.","correct":true,"id":"F"},{"text":"Assume more components always improve the outcome","why":"Additional infrastructure can add cost and maintenance without a relevant benefit.","correct":false,"id":"G"},{"text":"Claim relational systems cannot support analytical reporting","why":"Rejecting an unnecessary component does not justify a universal claim against its category or another platform's capabilities.","correct":false,"id":"H"}],"answer":"The architecture should fit actual workload characteristics rather than a label. Additional infrastructure can add cost and maintenance without a relevant benefit. A truthful account should describe the infrastructure actually used and needed. Rejecting an unnecessary component does not justify a universal claim against its category or another platform's capabilities.","source":{"anchor":"ksb-k12","guideSha256":"82a19528e64643915c69aafa73db1a3bcd08a4f6a7f6715d3baf0c435f7f4a97","excerpt":"Data architecture describes how sources, storage, transformation, governance and consumption fit together."},"id":"T22-E2-Q08"},{"ksb":"K12","objective":"Architecture terminology","prompt":"A project description says only 'Azure was used'. Which additions make it an informative architecture account?","options":[{"text":"Add unused components to make the architecture look complete","why":"The account should accurately represent actual use and responsibility.","correct":false,"id":"A"},{"text":"Infer a specific database service solely from the Azure label","why":"A broad provider name does not identify the storage or processing design.","correct":false,"id":"B"},{"text":"List vendor names without describing their roles","why":"Component roles and connections explain how the analysis actually operated.","correct":false,"id":"C"},{"text":"Treat a cloud platform as a substitute for those controls","why":"Cloud hosting does not remove organisational responsibilities and dependencies.","correct":false,"id":"D"},{"text":"Claim administration of every cloud service after using one connector","why":"The account should accurately represent actual use and responsibility.","correct":false,"id":"E"},{"text":"Name the actual services or components used where known","why":"A broad provider name does not identify the storage or processing design.","correct":true,"id":"F"},{"text":"Explain where data was stored, transformed and consumed","why":"Component roles and connections explain how the analysis actually operated.","correct":true,"id":"G"},{"text":"Explain access, ownership and refresh constraints","why":"Cloud hosting does not remove organisational responsibilities and dependencies.","correct":true,"id":"H"}],"answer":"A broad provider name does not identify the storage or processing design. Component roles and connections explain how the analysis actually operated. Cloud hosting does not remove organisational responsibilities and dependencies. The account should accurately represent actual use and responsibility.","source":{"anchor":"ksb-k12","guideSha256":"82a19528e64643915c69aafa73db1a3bcd08a4f6a7f6715d3baf0c435f7f4a97","excerpt":"Data architecture describes how sources, storage, transformation, governance and consumption fit together."},"id":"T22-E2-Q09"},{"ksb":"K12","objective":"Refresh dependency","prompt":"A dashboard refresh completes at 08:00, but an upstream load failed at 02:00. Which conclusions and actions are justified?","options":[{"text":"Escalate the failed load through its owner","why":"A failed dependency should be handled through responsible ownership and authorised change.","correct":true,"id":"A"},{"text":"Modify upstream production jobs without the relevant authority","why":"A failed dependency should be handled through responsible ownership and authorised change.","correct":false,"id":"B"},{"text":"A successful dashboard refresh proves the upstream load succeeded","why":"A downstream refresh can succeed while reading stale upstream content.","correct":false,"id":"C"},{"text":"Investigate only the chart rendering speed","why":"The timing issue concerns data dependencies, not just visual rendering.","correct":false,"id":"D"},{"text":"Show the refresh timestamp as though it were the newest transaction time","why":"Refresh time and the most recent source observation are different.","correct":false,"id":"E"},{"text":"The dashboard may display older warehouse data","why":"A downstream refresh can succeed while reading stale upstream content.","correct":true,"id":"F"},{"text":"Check the source-to-report refresh chain","why":"The timing issue concerns data dependencies, not just visual rendering.","correct":true,"id":"G"},{"text":"Communicate the represented data period","why":"Refresh time and the most recent source observation are different.","correct":true,"id":"H"}],"answer":"A downstream refresh can succeed while reading stale upstream content. The timing issue concerns data dependencies, not just visual rendering. Refresh time and the most recent source observation are different. A failed dependency should be handled through responsible ownership and authorised change.","source":{"anchor":"ksb-k12","guideSha256":"82a19528e64643915c69aafa73db1a3bcd08a4f6a7f6715d3baf0c435f7f4a97","excerpt":"Data architecture describes how sources, storage, transformation, governance and consumption fit together."},"id":"T22-E2-Q10"}]},{"id":"T23","title":"K13 · Principles of Statistics","description":"Descriptive measures, hypotheses, uncertainty and statistical decisions.","questions":[{"ksb":"K13","objective":"Correlation","prompt":"Two service measures have a positive correlation in an observational dataset. Which interpretations are defensible?","options":[{"text":"Interpret correlation as a difference in the measures' original units","why":"Correlation is a dimensionless association measure, not either of those quantities.","correct":false,"id":"A"},{"text":"Interpret a correlation coefficient as the percentage of records correctly predicted","why":"Correlation is a dimensionless association measure, not either of those quantities.","correct":false,"id":"B"},{"text":"Exclude alternative explanations because the coefficient is positive","why":"A positive relationship can arise through other variables or the collection process.","correct":false,"id":"C"},{"text":"Consider confounding and selection effects","why":"A positive relationship can arise through other variables or the collection process.","correct":true,"id":"D"},{"text":"Inspect a plot and possible influential observations","why":"A coefficient can hide nonlinearity, clusters or influential points.","correct":true,"id":"E"},{"text":"Infer the full relationship shape from the coefficient alone","why":"A coefficient can hide nonlinearity, clusters or influential points.","correct":false,"id":"F"},{"text":"The correlation proves changing one will change the other","why":"Association alone does not identify a causal intervention effect.","correct":false,"id":"G"},{"text":"Higher values of one tend to accompany higher values of the other in this sample","why":"Association alone does not identify a causal intervention effect.","correct":true,"id":"H"}],"answer":"Association alone does not identify a causal intervention effect. A coefficient can hide nonlinearity, clusters or influential points. A positive relationship can arise through other variables or the collection process. Correlation is a dimensionless association measure, not either of those quantities.","source":{"anchor":"ksb-k13","guideSha256":"04d385bb1be74eba3f31f9339493e5aa11dea86835de979e56753f3e109018db","excerpt":"Descriptive statistics summarise observed data; inferential statistics use a sample and assumptions to reason about a wider process or population."},"id":"T23-E2-Q01"},{"ksb":"K13","objective":"Hypothesis direction","prompt":"Before observing outcomes, a team plans a two-sided comparison of mean duration between services A and B. Which statements fit that plan?","options":[{"text":"Select alpha after seeing which value gives significance","why":"A pre-specified threshold avoids tailoring the decision rule to the observed p-value.","correct":false,"id":"A"},{"text":"The null must state that the observed sample means are identical","why":"The inferential hypothesis concerns population parameters rather than requiring equal sample summaries.","correct":false,"id":"B"},{"text":"The alternative can state that the population means differ","why":"A two-sided alternative allows a difference in either direction and should not be chosen after results.","correct":true,"id":"C"},{"text":"Choose the significance threshold before judging the result","why":"A pre-specified threshold avoids tailoring the decision rule to the observed p-value.","correct":true,"id":"D"},{"text":"The null can state equal population means","why":"The inferential hypothesis concerns population parameters rather than requiring equal sample summaries.","correct":true,"id":"E"},{"text":"Check whether the sampling design supports the intended comparison","why":"Independence and other assumptions depend on how observations were obtained.","correct":true,"id":"F"},{"text":"Treat the labels A and B as sufficient evidence of independence","why":"Independence and other assumptions depend on how observations were obtained.","correct":false,"id":"G"},{"text":"The alternative must favour whichever service later looks better","why":"A two-sided alternative allows a difference in either direction and should not be chosen after results.","correct":false,"id":"H"}],"answer":"The inferential hypothesis concerns population parameters rather than requiring equal sample summaries. A two-sided alternative allows a difference in either direction and should not be chosen after results. A pre-specified threshold avoids tailoring the decision rule to the observed p-value. Independence and other assumptions depend on how observations were obtained.","source":{"anchor":"ksb-k13","guideSha256":"04d385bb1be74eba3f31f9339493e5aa11dea86835de979e56753f3e109018db","excerpt":"Descriptive statistics summarise observed data; inferential statistics use a sample and assumptions to reason about a wider process or population."},"id":"T23-E2-Q02"},{"ksb":"K13","objective":"Spread and units","prompt":"A dataset of durations in days has variance 9 using the stated calculation. Which interpretations follow?","options":[{"text":"Conclude every duration is exactly three days from the mean","why":"Standard deviation summarises variation; it is not a fixed distance for every observation or a hard bound.","correct":false,"id":"A"},{"text":"Conclude no duration can exceed the mean by more than three days","why":"Standard deviation summarises variation; it is not a fixed distance for every observation or a hard bound.","correct":false,"id":"B"},{"text":"The corresponding standard deviation is 81 days","why":"Standard deviation is the square root of variance.","correct":false,"id":"C"},{"text":"Variance has the same units as the original durations","why":"Squaring deviations gives variance squared units; taking the root restores the original unit.","correct":false,"id":"D"},{"text":"The corresponding standard deviation is 3 days","why":"Standard deviation is the square root of variance.","correct":true,"id":"E"},{"text":"Standard deviation alone identifies the typical duration","why":"Spread and central tendency describe different features of a distribution.","correct":false,"id":"F"},{"text":"Variance is expressed in squared days","why":"Squaring deviations gives variance squared units; taking the root restores the original unit.","correct":true,"id":"G"},{"text":"Spread needs interpretation alongside the distribution and centre","why":"Spread and central tendency describe different features of a distribution.","correct":true,"id":"H"}],"answer":"Standard deviation is the square root of variance. Squaring deviations gives variance squared units; taking the root restores the original unit. Spread and central tendency describe different features of a distribution. Standard deviation summarises variation; it is not a fixed distance for every observation or a hard bound.","source":{"anchor":"ksb-k13","guideSha256":"04d385bb1be74eba3f31f9339493e5aa11dea86835de979e56753f3e109018db","excerpt":"Descriptive statistics summarise observed data; inferential statistics use a sample and assumptions to reason about a wider process or population."},"id":"T23-E2-Q03"},{"ksb":"K13","objective":"Paired measurements","prompt":"The same 20 staff members are measured before and after a training session. Which statistical considerations apply?","options":[{"text":"Attribute every observed improvement to training without further design evidence","why":"A before/after difference alone can have alternative explanations.","correct":false,"id":"A"},{"text":"Compare only the two group totals and ignore individual pairing","why":"Paired methods use the relationship between each person's measurements.","correct":false,"id":"B"},{"text":"Use an independent-samples test solely because there are two time labels","why":"Time labels do not remove the dependence created by measuring the same people.","correct":false,"id":"C"},{"text":"Treat the forty measurements as unrelated people","why":"Repeated measurements on the same person are related observations.","correct":false,"id":"D"},{"text":"Account for the pairing within each person","why":"Repeated measurements on the same person are related observations.","correct":true,"id":"E"},{"text":"Inspect within-person differences for a paired analysis","why":"Paired methods use the relationship between each person's measurements.","correct":true,"id":"F"},{"text":"Assess assumptions and other explanations for the change","why":"A before/after difference alone can have alternative explanations.","correct":true,"id":"G"},{"text":"Describe the design as two independent random samples","why":"Time labels do not remove the dependence created by measuring the same people.","correct":false,"id":"H"}],"answer":"Repeated measurements on the same person are related observations. Paired methods use the relationship between each person's measurements. A before/after difference alone can have alternative explanations. Time labels do not remove the dependence created by measuring the same people.","source":{"anchor":"ksb-k13","guideSha256":"04d385bb1be74eba3f31f9339493e5aa11dea86835de979e56753f3e109018db","excerpt":"Descriptive statistics summarise observed data; inferential statistics use a sample and assumptions to reason about a wider process or population."},"id":"T23-E2-Q04"},{"ksb":"K13","objective":"Non-significant result","prompt":"A planned comparison gives p = 0.18 at alpha = 0.05. Which explanation is appropriate?","options":[{"text":"Infer that sample size and variability are irrelevant","why":"Precision and ability to detect a difference depend on design, sample size and variation.","correct":false,"id":"A"},{"text":"Raise alpha after seeing the result to recover significance","why":"Changing the decision rule after seeing the result undermines the planned interpretation.","correct":false,"id":"B"},{"text":"The test does not reject the null at that threshold","why":"Failure to reject is not proof of exact equality.","correct":true,"id":"C"},{"text":"Consider the estimated difference and its uncertainty","why":"The estimate and uncertainty help explain what the data does and does not establish.","correct":true,"id":"D"},{"text":"The test proves the population means are identical","why":"Failure to reject is not proof of exact equality.","correct":false,"id":"E"},{"text":"Explain limitations of the evidence","why":"Changing the decision rule after seeing the result undermines the planned interpretation.","correct":true,"id":"F"},{"text":"Consider whether the study could detect a practically relevant difference","why":"Precision and ability to detect a difference depend on design, sample size and variation.","correct":true,"id":"G"},{"text":"Report only 'no effect' and omit the estimate","why":"The estimate and uncertainty help explain what the data does and does not establish.","correct":false,"id":"H"}],"answer":"Failure to reject is not proof of exact equality. The estimate and uncertainty help explain what the data does and does not establish. Precision and ability to detect a difference depend on design, sample size and variation. Changing the decision rule after seeing the result undermines the planned interpretation.","source":{"anchor":"ksb-k13","guideSha256":"04d385bb1be74eba3f31f9339493e5aa11dea86835de979e56753f3e109018db","excerpt":"Descriptive statistics summarise observed data; inferential statistics use a sample and assumptions to reason about a wider process or population."},"id":"T23-E2-Q05"},{"ksb":"K13","objective":"Interpreting a p-value","prompt":"A valid planned test gives p = 0.03 with alpha = 0.05. Which conclusions are justified?","options":[{"text":"Conclude the alternative has a 97% probability of being true","why":"Neither a posterior probability nor causation follows from this p-value alone.","correct":false,"id":"A"},{"text":"Conclude the tested factor caused the difference without a causal design","why":"Neither a posterior probability nor causation follows from this p-value alone.","correct":false,"id":"B"},{"text":"The p-value is calculated conditional on the null and test assumptions","why":"A p-value is not a posterior probability assigned to the hypothesis.","correct":true,"id":"C"},{"text":"Statistical significance proves the effect is operationally large","why":"A small p-value does not establish a large or useful effect.","correct":false,"id":"D"},{"text":"Retain the null because 0.03 is smaller than 0.05","why":"Under the planned rule, a p-value below alpha leads to rejection.","correct":false,"id":"E"},{"text":"There is a 3% probability that the null is true","why":"A p-value is not a posterior probability assigned to the hypothesis.","correct":false,"id":"F"},{"text":"Examine effect size and uncertainty before deciding practical importance","why":"A small p-value does not establish a large or useful effect.","correct":true,"id":"G"},{"text":"Reject the stated null at that threshold","why":"Under the planned rule, a p-value below alpha leads to rejection.","correct":true,"id":"H"}],"answer":"Under the planned rule, a p-value below alpha leads to rejection. A p-value is not a posterior probability assigned to the hypothesis. A small p-value does not establish a large or useful effect. Neither a posterior probability nor causation follows from this p-value alone.","source":{"anchor":"ksb-k13","guideSha256":"04d385bb1be74eba3f31f9339493e5aa11dea86835de979e56753f3e109018db","excerpt":"Descriptive statistics summarise observed data; inferential statistics use a sample and assumptions to reason about a wider process or population."},"id":"T23-E2-Q06"},{"ksb":"K13","objective":"Type I and II errors","prompt":"A test is used to flag whether a service's mean delay has changed. Which descriptions distinguish possible decision errors?","options":[{"text":"A Type I error rejects a true null","why":"Type I is a false rejection; failure to reject a false null is Type II.","correct":true,"id":"A"},{"text":"A Type I error fails to reject a false null","why":"Type I is a false rejection; failure to reject a false null is Type II.","correct":false,"id":"B"},{"text":"Remove error-risk discussion once the output is significant","why":"Statistical significance does not eliminate the possibility or consequences of a mistaken decision.","correct":false,"id":"C"},{"text":"A Type II error means the software failed to run","why":"A decision error concerns the test conclusion relative to reality, not a software exception.","correct":false,"id":"D"},{"text":"Every statistical error has the same practical cost","why":"A false alarm and a missed change can have different service consequences.","correct":false,"id":"E"},{"text":"Discuss threshold and design choices before interpreting results","why":"Statistical significance does not eliminate the possibility or consequences of a mistaken decision.","correct":true,"id":"F"},{"text":"A Type II error can miss a real change","why":"A decision error concerns the test conclusion relative to reality, not a software exception.","correct":true,"id":"G"},{"text":"Consequences depend on the operational decision","why":"A false alarm and a missed change can have different service consequences.","correct":true,"id":"H"}],"answer":"Type I is a false rejection; failure to reject a false null is Type II. A decision error concerns the test conclusion relative to reality, not a software exception. A false alarm and a missed change can have different service consequences. Statistical significance does not eliminate the possibility or consequences of a mistaken decision.","source":{"anchor":"ksb-k13","guideSha256":"04d385bb1be74eba3f31f9339493e5aa11dea86835de979e56753f3e109018db","excerpt":"Descriptive statistics summarise observed data; inferential statistics use a sample and assumptions to reason about a wider process or population."},"id":"T23-E2-Q07"},{"ksb":"K13","objective":"Practical significance","prompt":"A large dataset finds a statistically significant reduction of 0.02 days. The service says a useful improvement must be at least one day. Which conclusions are justified?","options":[{"text":"Describe the practical threshold as the significance level alpha","why":"Changing the estimate and confusing operational size with a probability threshold misrepresent the result.","correct":false,"id":"A"},{"text":"Present the estimate as an exact population change","why":"Estimates have uncertainty that affects interpretation.","correct":false,"id":"B"},{"text":"Compare the estimate with the practical threshold","why":"The stated decision threshold concerns effect magnitude, not just statistical significance.","correct":true,"id":"C"},{"text":"Assume a small p-value implies a large effect size","why":"A precise estimate of a small effect can be statistically significant.","correct":false,"id":"D"},{"text":"Report uncertainty around the estimated reduction","why":"Estimates have uncertainty that affects interpretation.","correct":true,"id":"E"},{"text":"Round 0.02 days up to one day to match the target","why":"Changing the estimate and confusing operational size with a probability threshold misrepresent the result.","correct":false,"id":"F"},{"text":"Explain why a large sample can detect a small difference","why":"A precise estimate of a small effect can be statistically significant.","correct":true,"id":"G"},{"text":"Declare operational success solely from the p-value","why":"The stated decision threshold concerns effect magnitude, not just statistical significance.","correct":false,"id":"H"}],"answer":"The stated decision threshold concerns effect magnitude, not just statistical significance. Estimates have uncertainty that affects interpretation. A precise estimate of a small effect can be statistically significant. Changing the estimate and confusing operational size with a probability threshold misrepresent the result.","source":{"anchor":"ksb-k13","guideSha256":"04d385bb1be74eba3f31f9339493e5aa11dea86835de979e56753f3e109018db","excerpt":"Descriptive statistics summarise observed data; inferential statistics use a sample and assumptions to reason about a wider process or population."},"id":"T23-E2-Q08"},{"ksb":"K13","objective":"Mean median mode","prompt":"Five observed durations are 2, 4, 4, 6 and 9 days. Which statements are correct?","options":[{"text":"Replacing 9 with 90 changes the mean but not this median","why":"The middle ordered value remains 4 even though the extreme increases the mean substantially.","correct":true,"id":"A"},{"text":"Replacing 9 with 90 changes this median to 6","why":"The middle ordered value remains 4 even though the extreme increases the mean substantially.","correct":false,"id":"B"},{"text":"The median is 6 days","why":"The middle value in the ordered five observations is 4.","correct":false,"id":"C"},{"text":"The mean is 5 days","why":"The sum is 25 days across five observations, so the arithmetic mean is 5.","correct":true,"id":"D"},{"text":"The mode is 9 days","why":"Four occurs twice, more often than any other value.","correct":false,"id":"E"},{"text":"The median is 4 days","why":"The middle value in the ordered five observations is 4.","correct":true,"id":"F"},{"text":"The mean is 4 days","why":"The sum is 25 days across five observations, so the arithmetic mean is 5.","correct":false,"id":"G"},{"text":"The mode is 4 days","why":"Four occurs twice, more often than any other value.","correct":true,"id":"H"}],"answer":"The sum is 25 days across five observations, so the arithmetic mean is 5. The middle value in the ordered five observations is 4. Four occurs twice, more often than any other value. The middle ordered value remains 4 even though the extreme increases the mean substantially.","source":{"anchor":"ksb-k13","guideSha256":"04d385bb1be74eba3f31f9339493e5aa11dea86835de979e56753f3e109018db","excerpt":"Descriptive statistics summarise observed data; inferential statistics use a sample and assumptions to reason about a wider process or population."},"id":"T23-E2-Q09"},{"ksb":"K13","objective":"Sample versus population","prompt":"A voluntary survey records responses from 60 of 500 service users. Which distinctions should accompany its average satisfaction score?","options":[{"text":"Add a p-value to make any sample representative","why":"Statistical calculations cannot by themselves repair an unsuitable sample design.","correct":false,"id":"A"},{"text":"Non-response may affect generalisation","why":"Representativeness depends on who responds and how the data was collected, not spreadsheet size.","correct":true,"id":"B"},{"text":"Treat a large response spreadsheet as proof of representativeness","why":"Representativeness depends on who responds and how the data was collected, not spreadsheet size.","correct":false,"id":"C"},{"text":"The average necessarily equals the full population's satisfaction","why":"Respondent summaries do not automatically establish a population parameter.","correct":false,"id":"D"},{"text":"The observed average describes the respondents","why":"Respondent summaries do not automatically establish a population parameter.","correct":true,"id":"E"},{"text":"Count the 440 non-respondents as neutral without justification","why":"Missing responses do not establish either neutrality or equality with respondents.","correct":false,"id":"F"},{"text":"Inferential claims require appropriate design and assumptions","why":"Statistical calculations cannot by themselves repair an unsuitable sample design.","correct":true,"id":"G"},{"text":"Infer that non-respondents have the same average merely because their scores are absent","why":"Missing responses do not establish either neutrality or equality with respondents.","correct":false,"id":"H"}],"answer":"Respondent summaries do not automatically establish a population parameter. Representativeness depends on who responds and how the data was collected, not spreadsheet size. Statistical calculations cannot by themselves repair an unsuitable sample design. Missing responses do not establish either neutrality or equality with respondents.","source":{"anchor":"ksb-k13","guideSha256":"04d385bb1be74eba3f31f9339493e5aa11dea86835de979e56753f3e109018db","excerpt":"Descriptive statistics summarise observed data; inferential statistics use a sample and assumptions to reason about a wider process or population."},"id":"T23-E2-Q10"}]},{"id":"T24","title":"K14 · Principles of Analytics Types","description":"Description, prediction, recommendation and their limits.","questions":[{"ksb":"K14","objective":"Descriptive purpose","prompt":"A report shows last quarter's requests, completion rates and median duration. Which statements describe its analytical role?","options":[{"text":"It summarises observed historical performance","why":"Historical summaries do not by themselves establish future outcomes.","correct":true,"id":"A"},{"text":"It can inform a later forecasting or decision stage","why":"Observed patterns can support further work without specifying the best action by themselves.","correct":true,"id":"B"},{"text":"A descriptive chart is already a complete action recommendation","why":"Observed patterns can support further work without specifying the best action by themselves.","correct":false,"id":"C"},{"text":"Infer a cause solely because a metric changed","why":"Audience use and temporal change do not establish causal explanation or prescriptive analysis.","correct":false,"id":"D"},{"text":"It necessarily predicts next quarter's exact performance","why":"Historical summaries do not by themselves establish future outcomes.","correct":false,"id":"E"},{"text":"Its definitions and included population affect interpretation","why":"Even historical summaries depend on scope and calculation choices.","correct":true,"id":"F"},{"text":"Call the report prescriptive solely because managers read it","why":"Audience use and temporal change do not establish causal explanation or prescriptive analysis.","correct":false,"id":"G"},{"text":"Descriptive results need no explanation of exclusions","why":"Even historical summaries depend on scope and calculation choices.","correct":false,"id":"H"}],"answer":"Historical summaries do not by themselves establish future outcomes. Even historical summaries depend on scope and calculation choices. Observed patterns can support further work without specifying the best action by themselves. Audience use and temporal change do not establish causal explanation or prescriptive analysis.","source":{"anchor":"ksb-k14","guideSha256":"5ce7abb6ad5d1959f0b2f32856f8152bd2020ed39cddc5e30c12ee30fcafed91","excerpt":"Descriptive analytics explains observed results: “What happened?” Predictive analytics estimates unknown or future outcomes with uncertainty: “What might happen?” Prescriptive analytics recommends actions using evidence, objectives and constraints: “What should we do?” In a fictional service project, descriptive analysis summarises completed requests and waiting-time distributions."},"id":"T24-E2-Q01"},{"ksb":"K14","objective":"Prescriptive constraints","prompt":"A validated forecast suggests more demand next month, but additional staff have a cost and a training lead time. Which steps move towards a defensible recommendation?","options":[{"text":"Treat the forecast as the only input to the decision","why":"Predictive information does not replace operational and financial judgement.","correct":false,"id":"A"},{"text":"Recommend unlimited extra staff solely from predicted demand","why":"A recommendation must account for available resources and constraints.","correct":false,"id":"B"},{"text":"Present the preferred action as guaranteed optimal without assumptions","why":"The recommendation depends on the objectives, constraints and uncertainty considered.","correct":false,"id":"C"},{"text":"Explain the trade-off and conditions for the proposed action","why":"The recommendation depends on the objectives, constraints and uncertainty considered.","correct":true,"id":"D"},{"text":"Consider costs, lead times and uncertainty","why":"Predictive information does not replace operational and financial judgement.","correct":true,"id":"E"},{"text":"Label the forecast curve itself as the complete prescription","why":"A prediction does not by itself specify an action or establish its causal effect.","correct":false,"id":"F"},{"text":"Compare feasible staffing options against service objectives","why":"A recommendation must account for available resources and constraints.","correct":true,"id":"G"},{"text":"Infer a causal benefit from a predictive correlation alone","why":"A prediction does not by itself specify an action or establish its causal effect.","correct":false,"id":"H"}],"answer":"A recommendation must account for available resources and constraints. Predictive information does not replace operational and financial judgement. The recommendation depends on the objectives, constraints and uncertainty considered. A prediction does not by itself specify an action or establish its causal effect.","source":{"anchor":"ksb-k14","guideSha256":"5ce7abb6ad5d1959f0b2f32856f8152bd2020ed39cddc5e30c12ee30fcafed91","excerpt":"Descriptive analytics explains observed results: “What happened?” Predictive analytics estimates unknown or future outcomes with uncertainty: “What might happen?” Prescriptive analytics recommends actions using evidence, objectives and constraints: “What should we do?” In a fictional service project, descriptive analysis summarises completed requests and waiting-time distributions."},"id":"T24-E2-Q02"},{"ksb":"K14","objective":"Preventing leakage","prompt":"A predictive model uses 'final resolution category' to estimate breaches when a case first arrives. Which changes address the problem?","options":[{"text":"Count the improved training fit as evidence that leakage is harmless","why":"Relabelling does not remove outcome information, and training fit does not resolve deployment invalidity.","correct":false,"id":"A"},{"text":"Retain the earlier score as the revised model's validated performance","why":"Changing features changes the model and requires appropriate evaluation.","correct":false,"id":"B"},{"text":"Re-evaluate the model using eligible features","why":"Changing features changes the model and requires appropriate evaluation.","correct":true,"id":"C"},{"text":"Describe all dataset columns as equally valid inputs","why":"Feature eligibility depends on what is known when the prediction must be made.","correct":false,"id":"D"},{"text":"Define the prediction point explicitly","why":"Feature eligibility depends on what is known when the prediction must be made.","correct":true,"id":"E"},{"text":"Hide the leaking field's name while keeping its values","why":"Relabelling does not remove outcome information, and training fit does not resolve deployment invalidity.","correct":false,"id":"F"},{"text":"Remove or replace information unavailable at arrival","why":"Retrospective availability does not make a feature usable at the actual prediction time.","correct":true,"id":"G"},{"text":"Keep the field because it improves retrospective accuracy","why":"Retrospective availability does not make a feature usable at the actual prediction time.","correct":false,"id":"H"}],"answer":"Retrospective availability does not make a feature usable at the actual prediction time. Changing features changes the model and requires appropriate evaluation. Feature eligibility depends on what is known when the prediction must be made. Relabelling does not remove outcome information, and training fit does not resolve deployment invalidity.","source":{"anchor":"ksb-k14","guideSha256":"5ce7abb6ad5d1959f0b2f32856f8152bd2020ed39cddc5e30c12ee30fcafed91","excerpt":"Descriptive analytics explains observed results: “What happened?” Predictive analytics estimates unknown or future outcomes with uncertainty: “What might happen?” Prescriptive analytics recommends actions using evidence, objectives and constraints: “What should we do?” In a fictional service project, descriptive analysis summarises completed requests and waiting-time distributions."},"id":"T24-E2-Q03"},{"ksb":"K14","objective":"Prediction target","prompt":"A team wants to estimate whether a new case will breach its deadline. Which choices fit a predictive task?","options":[{"text":"Validate predictions on suitable unseen cases","why":"Performance on the data used to fit a model can overstate its usefulness on new cases.","correct":true,"id":"A"},{"text":"Judge usefulness only by fit to the training cases","why":"Performance on the data used to fit a model can overstate its usefulness on new cases.","correct":false,"id":"B"},{"text":"Require an exact continuous-duration forecast for this binary target","why":"The stated target is a class outcome; a probability-based classification approach may fit it.","correct":false,"id":"C"},{"text":"Describe a 70% predicted probability as a guaranteed breach","why":"A predicted probability is not a certainty for an individual case.","correct":false,"id":"D"},{"text":"Consider a suitable classification approach such as logistic regression","why":"The stated target is a class outcome; a probability-based classification approach may fit it.","correct":true,"id":"E"},{"text":"Use the eventual breach result as an input at case opening","why":"A feature unavailable at prediction time would leak the outcome.","correct":false,"id":"F"},{"text":"Communicate uncertainty and the meaning of the predicted probability","why":"A predicted probability is not a certainty for an individual case.","correct":true,"id":"G"},{"text":"Define the breach outcome and prediction time","why":"A feature unavailable at prediction time would leak the outcome.","correct":true,"id":"H"}],"answer":"A feature unavailable at prediction time would leak the outcome. The stated target is a class outcome; a probability-based classification approach may fit it. Performance on the data used to fit a model can overstate its usefulness on new cases. A predicted probability is not a certainty for an individual case.","source":{"anchor":"ksb-k14","guideSha256":"5ce7abb6ad5d1959f0b2f32856f8152bd2020ed39cddc5e30c12ee30fcafed91","excerpt":"Descriptive analytics explains observed results: “What happened?” Predictive analytics estimates unknown or future outcomes with uncertainty: “What might happen?” Prescriptive analytics recommends actions using evidence, objectives and constraints: “What should we do?” In a fictional service project, descriptive analysis summarises completed requests and waiting-time distributions."},"id":"T24-E2-Q04"},{"ksb":"K14","objective":"Descriptive limitation","prompt":"A dashboard finds fewer complaints after a service change, while the feedback form also became harder to access. Which interpretation is defensible?","options":[{"text":"Qualify any recommendation based on the count alone","why":"An action recommendation needs to account for this measurement limitation.","correct":true,"id":"A"},{"text":"Infer the size of a causal effect from the raw count difference","why":"Absent feedback and a before/after difference do not establish those conclusions.","correct":false,"id":"B"},{"text":"Describe the reduction as proof of improved satisfaction","why":"The count changed, but the altered collection process offers another explanation.","correct":false,"id":"C"},{"text":"Recommend expanding the change solely from the unqualified count","why":"An action recommendation needs to account for this measurement limitation.","correct":false,"id":"D"},{"text":"Assume complaint counts measure the same process before and after","why":"A collection change can undermine comparability.","correct":false,"id":"E"},{"text":"Interpret non-submission as positive satisfaction","why":"Absent feedback and a before/after difference do not establish those conclusions.","correct":false,"id":"F"},{"text":"Investigate the changed feedback coverage","why":"A collection change can undermine comparability.","correct":true,"id":"G"},{"text":"Report the observed count reduction","why":"The count changed, but the altered collection process offers another explanation.","correct":true,"id":"H"}],"answer":"The count changed, but the altered collection process offers another explanation. A collection change can undermine comparability. An action recommendation needs to account for this measurement limitation. Absent feedback and a before/after difference do not establish those conclusions.","source":{"anchor":"ksb-k14","guideSha256":"5ce7abb6ad5d1959f0b2f32856f8152bd2020ed39cddc5e30c12ee30fcafed91","excerpt":"Descriptive analytics explains observed results: “What happened?” Predictive analytics estimates unknown or future outcomes with uncertainty: “What might happen?” Prescriptive analytics recommends actions using evidence, objectives and constraints: “What should we do?” In a fictional service project, descriptive analysis summarises completed requests and waiting-time distributions."},"id":"T24-E2-Q05"},{"ksb":"K14","objective":"Forecast versus explanation","prompt":"A model predicts demand well using season and location. Which claims are justified by predictive performance alone?","options":[{"text":"Location has been proved to cause the observed demand difference","why":"Predictive association alone does not establish a causal mechanism.","correct":false,"id":"A"},{"text":"Infer that changing the location code will change real demand","why":"Altering a recorded feature and interpreting a coefficient causally require evidence beyond prediction accuracy.","correct":false,"id":"B"},{"text":"Historical validation guarantees permanent future accuracy","why":"Relationships and populations can change after validation.","correct":false,"id":"C"},{"text":"Performance needs monitoring when conditions change","why":"Relationships and populations can change after validation.","correct":true,"id":"D"},{"text":"The model may be useful for this prediction task under tested conditions","why":"Predictive association alone does not establish a causal mechanism.","correct":true,"id":"E"},{"text":"Treat good prediction as proof that every coefficient is causal","why":"Altering a recorded feature and interpreting a coefficient causally require evidence beyond prediction accuracy.","correct":false,"id":"F"},{"text":"Apply the same performance claim to every region and time horizon","why":"Evaluation supports claims within its tested context, not unlimited extrapolation.","correct":false,"id":"G"},{"text":"State the population and horizon for which it was evaluated","why":"Evaluation supports claims within its tested context, not unlimited extrapolation.","correct":true,"id":"H"}],"answer":"Predictive association alone does not establish a causal mechanism. Relationships and populations can change after validation. Evaluation supports claims within its tested context, not unlimited extrapolation. Altering a recorded feature and interpreting a coefficient causally require evidence beyond prediction accuracy.","source":{"anchor":"ksb-k14","guideSha256":"5ce7abb6ad5d1959f0b2f32856f8152bd2020ed39cddc5e30c12ee30fcafed91","excerpt":"Descriptive analytics explains observed results: “What happened?” Predictive analytics estimates unknown or future outcomes with uncertainty: “What might happen?” Prescriptive analytics recommends actions using evidence, objectives and constraints: “What should we do?” In a fictional service project, descriptive analysis summarises completed requests and waiting-time distributions."},"id":"T24-E2-Q06"},{"ksb":"K14","objective":"Linear versus logistic","prompt":"One task estimates numerical completion days; another estimates breach probability. Which distinctions guide method selection?","options":[{"text":"Compare a probability classifier and duration model using an unexplained common score","why":"Different prediction tasks can need different evaluation measures.","correct":false,"id":"A"},{"text":"Logistic regression may suit the binary breach outcome","why":"The target's meaning should guide the modelling approach.","correct":true,"id":"B"},{"text":"Linear regression may suit the numerical outcome under appropriate assumptions","why":"Logistic regression is commonly used for a defined class probability, not an exact continuous duration.","correct":true,"id":"C"},{"text":"A binary target must be treated as an unrestricted continuous amount","why":"The target's meaning should guide the modelling approach.","correct":false,"id":"D"},{"text":"Evaluate each model with metrics suited to its objective","why":"Different prediction tasks can need different evaluation measures.","correct":true,"id":"E"},{"text":"Logistic regression directly guarantees exact completion days","why":"Logistic regression is commonly used for a defined class probability, not an exact continuous duration.","correct":false,"id":"F"},{"text":"Treat the method name as proof of a suitable model","why":"A method label does not establish that its application meets the actual requirements.","correct":false,"id":"G"},{"text":"Check features, assumptions and deployment context","why":"A method label does not establish that its application meets the actual requirements.","correct":true,"id":"H"}],"answer":"Logistic regression is commonly used for a defined class probability, not an exact continuous duration. The target's meaning should guide the modelling approach. Different prediction tasks can need different evaluation measures. A method label does not establish that its application meets the actual requirements.","source":{"anchor":"ksb-k14","guideSha256":"5ce7abb6ad5d1959f0b2f32856f8152bd2020ed39cddc5e30c12ee30fcafed91","excerpt":"Descriptive analytics explains observed results: “What happened?” Predictive analytics estimates unknown or future outcomes with uncertainty: “What might happen?” Prescriptive analytics recommends actions using evidence, objectives and constraints: “What should we do?” In a fictional service project, descriptive analysis summarises completed requests and waiting-time distributions."},"id":"T24-E2-Q07"},{"ksb":"K14","objective":"Recommendation uncertainty","prompt":"A capacity model performs better than a baseline on one holdout, but future demand may shift. Which recommendation is balanced?","options":[{"text":"Select an option solely by the smallest training error","why":"Training error does not capture unseen performance or decision costs.","correct":false,"id":"A"},{"text":"Claim the model will beat the baseline in every future period","why":"One evaluation supports a bounded finding rather than a universal guarantee.","correct":false,"id":"B"},{"text":"Consider a plan that can be reviewed as demand is observed","why":"Future shifts make review and monitoring relevant.","correct":true,"id":"C"},{"text":"Commit permanently without monitoring because the model was validated","why":"Future shifts make review and monitoring relevant.","correct":false,"id":"D"},{"text":"Describe the observed validation advantage and its scope","why":"One evaluation supports a bounded finding rather than a universal guarantee.","correct":true,"id":"E"},{"text":"Remove uncertainty to make the recommendation sound decisive","why":"A useful recommendation can be clear while still stating its conditions and limitations.","correct":false,"id":"F"},{"text":"Explain feasible alternatives and operational costs","why":"Training error does not capture unseen performance or decision costs.","correct":true,"id":"G"},{"text":"State material assumptions behind the proposed action","why":"A useful recommendation can be clear while still stating its conditions and limitations.","correct":true,"id":"H"}],"answer":"One evaluation supports a bounded finding rather than a universal guarantee. Future shifts make review and monitoring relevant. Training error does not capture unseen performance or decision costs. A useful recommendation can be clear while still stating its conditions and limitations.","source":{"anchor":"ksb-k14","guideSha256":"5ce7abb6ad5d1959f0b2f32856f8152bd2020ed39cddc5e30c12ee30fcafed91","excerpt":"Descriptive analytics explains observed results: “What happened?” Predictive analytics estimates unknown or future outcomes with uncertainty: “What might happen?” Prescriptive analytics recommends actions using evidence, objectives and constraints: “What should we do?” In a fictional service project, descriptive analysis summarises completed requests and waiting-time distributions."},"id":"T24-E2-Q08"},{"ksb":"K14","objective":"Analytics chain","prompt":"A service first summarises delays, then predicts future workload, then compares rota options. Which mapping is accurate?","options":[{"text":"Summarising observed delays is predictive solely because dates are present","why":"Historical data containing dates does not make a summary a forecast.","correct":false,"id":"A"},{"text":"Summarising observed delays is descriptive","why":"Historical data containing dates does not make a summary a forecast.","correct":true,"id":"B"},{"text":"Estimating future workload is predictive","why":"Prediction estimates outcomes; it does not necessarily select an action.","correct":true,"id":"C"},{"text":"Treat the three labels as evidence that every stage was actually performed","why":"A project account needs the actual work and how the stages informed one another.","correct":false,"id":"D"},{"text":"Estimating future workload is prescriptive solely because staff will use it","why":"Prediction estimates outcomes; it does not necessarily select an action.","correct":false,"id":"E"},{"text":"Comparing rota actions is unrelated to objectives or constraints","why":"A useful action comparison incorporates the decision's objectives and practical limits.","correct":false,"id":"F"},{"text":"Explain the connection and uncertainty between stages","why":"A project account needs the actual work and how the stages informed one another.","correct":true,"id":"G"},{"text":"Comparing feasible rota actions can support prescriptive analysis","why":"A useful action comparison incorporates the decision's objectives and practical limits.","correct":true,"id":"H"}],"answer":"Historical data containing dates does not make a summary a forecast. Prediction estimates outcomes; it does not necessarily select an action. A useful action comparison incorporates the decision's objectives and practical limits. A project account needs the actual work and how the stages informed one another.","source":{"anchor":"ksb-k14","guideSha256":"5ce7abb6ad5d1959f0b2f32856f8152bd2020ed39cddc5e30c12ee30fcafed91","excerpt":"Descriptive analytics explains observed results: “What happened?” Predictive analytics estimates unknown or future outcomes with uncertainty: “What might happen?” Prescriptive analytics recommends actions using evidence, objectives and constraints: “What should we do?” In a fictional service project, descriptive analysis summarises completed requests and waiting-time distributions."},"id":"T24-E2-Q09"},{"ksb":"K14","objective":"Truthful application","prompt":"Your project contains descriptive analysis and an evidence-based recommendation, but no predictive model was built. Which account is appropriate?","options":[{"text":"Add a future date label to historical values and call them validated predictions","why":"Neither altered labels nor a recommendation establishes an actual predictive workflow.","correct":false,"id":"A"},{"text":"Check relevant evidence requirements and identify any gap honestly","why":"Knowledge of a method does not itself demonstrate using it.","correct":true,"id":"B"},{"text":"Infer that knowing the definitions proves practical application","why":"Knowledge of a method does not itself demonstrate using it.","correct":false,"id":"C"},{"text":"Claim the recommendation proves an unseen predictive stage existed","why":"Neither altered labels nor a recommendation establishes an actual predictive workflow.","correct":false,"id":"D"},{"text":"Describe the analytics actually performed","why":"An account should not claim a model or forecast that was not performed.","correct":true,"id":"E"},{"text":"Rename the historical chart as a forecast to cover every label","why":"An account should not claim a model or forecast that was not performed.","correct":false,"id":"F"},{"text":"Explain any predictive knowledge with a clearly labelled example","why":"A learning example and genuine applied work must remain distinct.","correct":true,"id":"G"},{"text":"Present a hypothetical regression as deployed project work","why":"A learning example and genuine applied work must remain distinct.","correct":false,"id":"H"}],"answer":"An account should not claim a model or forecast that was not performed. A learning example and genuine applied work must remain distinct. Knowledge of a method does not itself demonstrate using it. Neither altered labels nor a recommendation establishes an actual predictive workflow.","source":{"anchor":"ksb-k14","guideSha256":"5ce7abb6ad5d1959f0b2f32856f8152bd2020ed39cddc5e30c12ee30fcafed91","excerpt":"Descriptive analytics explains observed results: “What happened?” Predictive analytics estimates unknown or future outcomes with uncertainty: “What might happen?” Prescriptive analytics recommends actions using evidence, objectives and constraints: “What should we do?” In a fictional service project, descriptive analysis summarises completed requests and waiting-time distributions."},"id":"T24-E2-Q10"}]},{"id":"T25","title":"K15 · Data Ethics","description":"Collection, fairness, bias, transparency, accountability and consent.","questions":[{"ksb":"K15","objective":"Collection context","prompt":"A feedback dataset was collected through an optional online form. Which ethical considerations should accompany its use to prioritise services?","options":[{"text":"Limit claims to what the collection supports","why":"The collection process can constrain generalisation to the full service population.","correct":true,"id":"A"},{"text":"Explain who could access and respond to the form","why":"Absence from an optional channel does not establish absence of need or dissatisfaction.","correct":true,"id":"B"},{"text":"Treat all non-respondents as having no concerns","why":"Absence from an optional channel does not establish absence of need or dissatisfaction.","correct":false,"id":"C"},{"text":"Treat the mere existence of the data as justification for any use","why":"Ethical assessment considers purpose and consequences rather than availability alone.","correct":false,"id":"D"},{"text":"Assume the largest response group represents every user","why":"Participation patterns can produce unequal representation.","correct":false,"id":"E"},{"text":"Consider digitally excluded users and missing perspectives","why":"Participation patterns can produce unequal representation.","correct":true,"id":"F"},{"text":"Describe the collection purpose and proposed decision use","why":"Ethical assessment considers purpose and consequences rather than availability alone.","correct":true,"id":"G"},{"text":"Present the respondent percentages as unquestioned population opinion","why":"The collection process can constrain generalisation to the full service population.","correct":false,"id":"H"}],"answer":"Absence from an optional channel does not establish absence of need or dissatisfaction. Participation patterns can produce unequal representation. Ethical assessment considers purpose and consequences rather than availability alone. The collection process can constrain generalisation to the full service population.","source":{"anchor":"ksb-k15","guideSha256":"1d702236151e0909ddb381cdf3973f8b40cbe3601a180e66940fe44712f81256","excerpt":"Ethics asks whether data use is appropriate and fair, including where a use might be legally permitted."},"id":"T25-E2-Q01"},{"ksb":"K15","objective":"Unintended incentives","prompt":"A proposed dashboard rewards teams solely for closing cases quickly. Complex cases may take longer for legitimate reasons. Which concerns should be raised?","options":[{"text":"Examine case complexity and quality alongside speed","why":"A transparent assessment should address complexity rather than conceal inconvenient cases.","correct":true,"id":"A"},{"text":"The metric may encourage premature closure","why":"A narrow target can reward behaviour that improves the metric without improving service quality.","correct":true,"id":"B"},{"text":"Describe the measure as neutral because it is numerical","why":"Numerical measures involve choices and can affect behaviour; they do not establish motives or eliminate judgement.","correct":false,"id":"C"},{"text":"Remove difficult cases without disclosing the exclusion","why":"A transparent assessment should address complexity rather than conceal inconvenient cases.","correct":false,"id":"D"},{"text":"Infer staff motives solely from the ranking","why":"Numerical measures involve choices and can affect behaviour; they do not establish motives or eliminate judgement.","correct":false,"id":"E"},{"text":"Faster recorded closure necessarily means a better user outcome","why":"A narrow target can reward behaviour that improves the metric without improving service quality.","correct":false,"id":"F"},{"text":"Discuss the intended and possible unintended effects with responsible stakeholders","why":"Foreseeable impacts should inform design and review before use where possible.","correct":true,"id":"G"},{"text":"Deploy first because an ethical review can consider only actual harm","why":"Foreseeable impacts should inform design and review before use where possible.","correct":false,"id":"H"}],"answer":"A narrow target can reward behaviour that improves the metric without improving service quality. A transparent assessment should address complexity rather than conceal inconvenient cases. Foreseeable impacts should inform design and review before use where possible. Numerical measures involve choices and can affect behaviour; they do not establish motives or eliminate judgement.","source":{"anchor":"ksb-k15","guideSha256":"1d702236151e0909ddb381cdf3973f8b40cbe3601a180e66940fe44712f81256","excerpt":"Ethics asks whether data use is appropriate and fair, including where a use might be legally permitted."},"id":"T25-E2-Q02"},{"ksb":"K15","objective":"Proxy bias","prompt":"A model excludes ethnicity but uses postcode and service-access history. Which fairness considerations remain?","options":[{"text":"Consider how historical access shaped the training records","why":"Unequal access can affect who appears in the data and what is observed.","correct":true,"id":"A"},{"text":"Treat recorded service use as a complete measure of need","why":"Unequal access can affect who appears in the data and what is observed.","correct":false,"id":"B"},{"text":"Removing one sensitive field guarantees absence of bias","why":"Proxies and historical patterns can retain group-related effects.","correct":false,"id":"C"},{"text":"Other features may reflect protected or disadvantaged groups","why":"Proxies and historical patterns can retain group-related effects.","correct":true,"id":"D"},{"text":"Infer unfairness is impossible when no direct group label is an input","why":"Neither opacity nor omission of a direct label establishes fair outcomes.","correct":false,"id":"E"},{"text":"Examine relevant group outcomes where lawful and appropriate","why":"Aggregate performance can hide unequal errors or impacts.","correct":true,"id":"F"},{"text":"Assess fairness only through overall accuracy","why":"Aggregate performance can hide unequal errors or impacts.","correct":false,"id":"G"},{"text":"Infer that a complex model is fair because its rules are hard to inspect","why":"Neither opacity nor omission of a direct label establishes fair outcomes.","correct":false,"id":"H"}],"answer":"Proxies and historical patterns can retain group-related effects. Aggregate performance can hide unequal errors or impacts. Unequal access can affect who appears in the data and what is observed. Neither opacity nor omission of a direct label establishes fair outcomes.","source":{"anchor":"ksb-k15","guideSha256":"1d702236151e0909ddb381cdf3973f8b40cbe3601a180e66940fe44712f81256","excerpt":"Ethics asks whether data use is appropriate and fair, including where a use might be legally permitted."},"id":"T25-E2-Q03"},{"ksb":"K15","objective":"Accountability for decisions","prompt":"An analysis recommends prioritising some applicants for a scarce service. Which governance arrangements support accountability?","options":[{"text":"Provide a suitable review or challenge route","why":"Consequential recommendations need appropriate scrutiny rather than unquestionable status.","correct":true,"id":"A"},{"text":"End responsibility immediately after the first deployment","why":"Impacts may emerge during use and require ongoing review.","correct":false,"id":"B"},{"text":"Treat a model score as beyond question","why":"Consequential recommendations need appropriate scrutiny rather than unquestionable status.","correct":false,"id":"C"},{"text":"Monitor outcomes and unintended effects where relevant","why":"Impacts may emerge during use and require ongoing review.","correct":true,"id":"D"},{"text":"Retain only the final ranked list","why":"A decision trail helps explain how and why priorities were proposed.","correct":false,"id":"E"},{"text":"Identify who is responsible for approving the use","why":"Organisational decision responsibility cannot simply be displaced onto a tool provider.","correct":true,"id":"F"},{"text":"Treat the software vendor as the sole owner of every service decision","why":"Organisational decision responsibility cannot simply be displaced onto a tool provider.","correct":false,"id":"G"},{"text":"Record the evidence, assumptions and important trade-offs","why":"A decision trail helps explain how and why priorities were proposed.","correct":true,"id":"H"}],"answer":"Organisational decision responsibility cannot simply be displaced onto a tool provider. A decision trail helps explain how and why priorities were proposed. Consequential recommendations need appropriate scrutiny rather than unquestionable status. Impacts may emerge during use and require ongoing review.","source":{"anchor":"ksb-k15","guideSha256":"1d702236151e0909ddb381cdf3973f8b40cbe3601a180e66940fe44712f81256","excerpt":"Ethics asks whether data use is appropriate and fair, including where a use might be legally permitted."},"id":"T25-E2-Q04"},{"ksb":"K15","objective":"Consent scope","prompt":"Participants consented to a defined research use. A new team proposes unrelated profiling. Which ethical questions arise?","options":[{"text":"Assess only whether profiling is technically possible","why":"Ethical suitability concerns consequences and expectations as well as technical feasibility.","correct":false,"id":"A"},{"text":"Assume another legal basis automatically settles every ethical concern","why":"Legal-basis analysis and ethical evaluation are related but not identical.","correct":false,"id":"B"},{"text":"Consult responsible governance roles on the changed purpose","why":"A materially different use needs the appropriate responsible assessment.","correct":true,"id":"C"},{"text":"Treat any prior consent as permission for unlimited future use","why":"Agreement to one defined use does not automatically authorise every later purpose.","correct":false,"id":"D"},{"text":"Consider people's reasonable expectations and potential harm","why":"Ethical suitability concerns consequences and expectations as well as technical feasibility.","correct":true,"id":"E"},{"text":"Let an analyst privately reinterpret the consent wording","why":"A materially different use needs the appropriate responsible assessment.","correct":false,"id":"F"},{"text":"Assume consent is always the only possible legal basis in every context","why":"Legal-basis analysis and ethical evaluation are related but not identical.","correct":false,"id":"G"},{"text":"Check whether the proposed use fits the original agreement and conditions","why":"Agreement to one defined use does not automatically authorise every later purpose.","correct":true,"id":"H"}],"answer":"Agreement to one defined use does not automatically authorise every later purpose. Ethical suitability concerns consequences and expectations as well as technical feasibility. A materially different use needs the appropriate responsible assessment. Legal-basis analysis and ethical evaluation are related but not identical.","source":{"anchor":"ksb-k15","guideSha256":"1d702236151e0909ddb381cdf3973f8b40cbe3601a180e66940fe44712f81256","excerpt":"Ethics asks whether data use is appropriate and fair, including where a use might be legally permitted."},"id":"T25-E2-Q05"},{"ksb":"K15","objective":"Transparency boundaries","prompt":"A public briefing should explain how a sensitive analysis was conducted. Which approach supports transparency responsibly?","options":[{"text":"Treat publication of a technical file as sufficient communication for everyone","why":"A technical artefact alone may not make the reasoning understandable or contestable.","correct":false,"id":"A"},{"text":"Suppress all methodological explanation because some inputs are sensitive","why":"Credentials should remain protected, while sensitivity does not automatically prevent safe explanation of methods.","correct":false,"id":"B"},{"text":"Provide an appropriate route for questions or challenge","why":"A technical artefact alone may not make the reasoning understandable or contestable.","correct":true,"id":"C"},{"text":"Publish only a conclusion without its basis","why":"People need sufficient context to understand and challenge the conclusion.","correct":false,"id":"D"},{"text":"Describe methods, assumptions and limitations accessibly","why":"Methodological transparency need not involve exposing personal records.","correct":true,"id":"E"},{"text":"Explain relevant data sources and population coverage","why":"People need sufficient context to understand and challenge the conclusion.","correct":true,"id":"F"},{"text":"Release identifying raw records as the default proof of openness","why":"Methodological transparency need not involve exposing personal records.","correct":false,"id":"G"},{"text":"Reveal authentication details to demonstrate access legitimacy","why":"Credentials should remain protected, while sensitivity does not automatically prevent safe explanation of methods.","correct":false,"id":"H"}],"answer":"Methodological transparency need not involve exposing personal records. People need sufficient context to understand and challenge the conclusion. A technical artefact alone may not make the reasoning understandable or contestable. Credentials should remain protected, while sensitivity does not automatically prevent safe explanation of methods.","source":{"anchor":"ksb-k15","guideSha256":"1d702236151e0909ddb381cdf3973f8b40cbe3601a180e66940fe44712f81256","excerpt":"Ethics asks whether data use is appropriate and fair, including where a use might be legally permitted."},"id":"T25-E2-Q06"},{"ksb":"K15","objective":"Small-group disclosure","prompt":"A qualitative report quotes a rare case with distinctive details, but removes the person's name. Which review is appropriate?","options":[{"text":"Assess identification from the combination of details","why":"Distinctive combinations can identify someone without a direct name.","correct":true,"id":"A"},{"text":"Add more personal detail to make the case persuasive without checking","why":"Persuasive value does not establish an ethical basis for disclosing identifying details.","correct":false,"id":"B"},{"text":"Conclude the quote is anonymous because its name was removed","why":"Distinctive combinations can identify someone without a direct name.","correct":false,"id":"C"},{"text":"Treat an emotionally compelling quote as automatically suitable evidence for publication","why":"Persuasive value does not establish an ethical basis for disclosing identifying details.","correct":false,"id":"D"},{"text":"Replace the name with initials and assume disclosure risk is resolved","why":"Initials or pseudonyms do not necessarily remove identifying context.","correct":false,"id":"E"},{"text":"Consider safer paraphrasing or aggregation while preserving meaning","why":"Initials or pseudonyms do not necessarily remove identifying context.","correct":true,"id":"F"},{"text":"Assume an internal presentation has no privacy or ethical implications","why":"Audience affects risk but does not eliminate the need for review.","correct":false,"id":"G"},{"text":"Check the intended audience and any relevant permission or restrictions","why":"Audience affects risk but does not eliminate the need for review.","correct":true,"id":"H"}],"answer":"Distinctive combinations can identify someone without a direct name. Initials or pseudonyms do not necessarily remove identifying context. Audience affects risk but does not eliminate the need for review. Persuasive value does not establish an ethical basis for disclosing identifying details.","source":{"anchor":"ksb-k15","guideSha256":"1d702236151e0909ddb381cdf3973f8b40cbe3601a180e66940fe44712f81256","excerpt":"Ethics asks whether data use is appropriate and fair, including where a use might be legally permitted."},"id":"T25-E2-Q07"},{"ksb":"K15","objective":"Withdrawing an overclaim","prompt":"A draft report describes a convenience sample as 'all residents'. Which correction best supports ethical communication?","options":[{"text":"Add a small footnote while leaving a contradictory headline unchanged","why":"A caveat does not adequately correct a headline that still makes an unsupported claim.","correct":false,"id":"A"},{"text":"Explain the limitation to the decision-maker","why":"Accountability includes transparent correction of material interpretation errors.","correct":true,"id":"B"},{"text":"Revise unsupported conclusions and recommendations","why":"A caveat does not adequately correct a headline that still makes an unsupported claim.","correct":true,"id":"C"},{"text":"Treat the sample's large spreadsheet size as proof of representativeness","why":"Neither unsupported weighting nor file size establishes the missing sampling justification.","correct":false,"id":"D"},{"text":"Conceal the correction to protect the analyst's reputation","why":"Accountability includes transparent correction of material interpretation errors.","correct":false,"id":"E"},{"text":"Invent weights without a justified basis to simulate population coverage","why":"Neither unsupported weighting nor file size establishes the missing sampling justification.","correct":false,"id":"F"},{"text":"Name the actual respondent population","why":"Clarity should not be achieved by misrepresenting who the data covers.","correct":true,"id":"G"},{"text":"Retain the broad claim because it is easier to understand","why":"Clarity should not be achieved by misrepresenting who the data covers.","correct":false,"id":"H"}],"answer":"Clarity should not be achieved by misrepresenting who the data covers. A caveat does not adequately correct a headline that still makes an unsupported claim. Accountability includes transparent correction of material interpretation errors. Neither unsupported weighting nor file size establishes the missing sampling justification.","source":{"anchor":"ksb-k15","guideSha256":"1d702236151e0909ddb381cdf3973f8b40cbe3601a180e66940fe44712f81256","excerpt":"Ethics asks whether data use is appropriate and fair, including where a use might be legally permitted."},"id":"T25-E2-Q08"},{"ksb":"K15","objective":"Ethical framework use","prompt":"An analyst references the UK Government Data Ethics Framework in a project. Which use of that reference is meaningful?","options":[{"text":"Replace discussion of impacts with a list of technical tools","why":"Tools alone do not explain ethical consequences or responsibility.","correct":false,"id":"A"},{"text":"Cite the framework title as sufficient proof of ethical compliance","why":"A reference needs to inform the project's reasoning and actions.","correct":false,"id":"B"},{"text":"Mark every concern resolved simply because a checklist was opened","why":"Completing a review process requires substantive consideration rather than visiting a checklist.","correct":false,"id":"C"},{"text":"Record identified risks, mitigations and residual concerns","why":"Completing a review process requires substantive consideration rather than visiting a checklist.","correct":true,"id":"D"},{"text":"Explain fairness, transparency and accountability considerations in context","why":"Tools alone do not explain ethical consequences or responsibility.","correct":true,"id":"E"},{"text":"Explain where specialist or stakeholder input was needed","why":"Frameworks guide reasoning but do not eliminate contextual judgement and appropriate consultation.","correct":true,"id":"F"},{"text":"Apply its relevant questions to the actual data and decision","why":"A reference needs to inform the project's reasoning and actions.","correct":true,"id":"G"},{"text":"Claim the framework removes all need for judgement","why":"Frameworks guide reasoning but do not eliminate contextual judgement and appropriate consultation.","correct":false,"id":"H"}],"answer":"A reference needs to inform the project's reasoning and actions. Tools alone do not explain ethical consequences or responsibility. Completing a review process requires substantive consideration rather than visiting a checklist. Frameworks guide reasoning but do not eliminate contextual judgement and appropriate consultation.","source":{"anchor":"ksb-k15","guideSha256":"1d702236151e0909ddb381cdf3973f8b40cbe3601a180e66940fe44712f81256","excerpt":"Ethics asks whether data use is appropriate and fair, including where a use might be legally permitted."},"id":"T25-E2-Q09"},{"ksb":"K15","objective":"Fair service comparison","prompt":"Raw complaint counts are used to rank services with very different user populations and access channels. Which ethical analytical choices are justified?","options":[{"text":"Treat the highest count as proof of the worst service","why":"Counts can reflect service size and accessibility of feedback as well as performance.","correct":false,"id":"A"},{"text":"Consider who could be harmed by an unsupported ranking","why":"Ethical evaluation includes consequences for affected groups, not just presentation quality.","correct":true,"id":"B"},{"text":"Assume a mathematically correct count makes every use fair","why":"Correct arithmetic does not by itself establish a fair interpretation or decision.","correct":false,"id":"C"},{"text":"Evaluate only whether the ranking looks clear","why":"Ethical evaluation includes consequences for affected groups, not just presentation quality.","correct":false,"id":"D"},{"text":"Examine denominators and opportunities to give feedback","why":"Counts can reflect service size and accessibility of feedback as well as performance.","correct":true,"id":"E"},{"text":"Seek appropriate stakeholder scrutiny of the proposed use","why":"Correct arithmetic does not by itself establish a fair interpretation or decision.","correct":true,"id":"F"},{"text":"Omit limitations to avoid weakening the ranking","why":"Omitting material context can create unfair or misleading conclusions.","correct":false,"id":"G"},{"text":"Explain coverage and comparability limitations","why":"Omitting material context can create unfair or misleading conclusions.","correct":true,"id":"H"}],"answer":"Counts can reflect service size and accessibility of feedback as well as performance. Omitting material context can create unfair or misleading conclusions. Ethical evaluation includes consequences for affected groups, not just presentation quality. Correct arithmetic does not by itself establish a fair interpretation or decision.","source":{"anchor":"ksb-k15","guideSha256":"1d702236151e0909ddb381cdf3973f8b40cbe3601a180e66940fe44712f81256","excerpt":"Ethics asks whether data use is appropriate and fair, including where a use might be legally permitted."},"id":"T25-E2-Q10"}]},{"id":"T26","title":"S1 · Operating Data Systems in Compliance","description":"Privacy by Design across actual data-system use.","questions":[{"ksb":"S1","objective":"Output checking","prompt":"A report is ready for external release. It contains aggregate counts and downloadable row-level detail. Which checks address the actual system behaviour?","options":[{"text":"Treat a successful upload as the release approval","why":"Technical publication success does not establish the required governance decision.","correct":false,"id":"A"},{"text":"Test filters and drill-down paths for sensitive detail","why":"Actual behaviour should be checked rather than inferred from appearance.","correct":true,"id":"B"},{"text":"Approve release solely from the visible aggregate screen","why":"Exports can disclose detail absent from the initial visual.","correct":false,"id":"C"},{"text":"Assume the internal testing permissions are appropriate externally","why":"A new audience can require different access and disclosure decisions.","correct":false,"id":"D"},{"text":"Treat disabled-looking controls as proof of inaccessible data","why":"Actual behaviour should be checked rather than inferred from appearance.","correct":false,"id":"E"},{"text":"Record the release decision through the relevant process","why":"Technical publication success does not establish the required governance decision.","correct":true,"id":"F"},{"text":"Review the downloadable data as well as the displayed chart","why":"Exports can disclose detail absent from the initial visual.","correct":true,"id":"G"},{"text":"Verify permissions and disclosure treatments for the intended audience","why":"A new audience can require different access and disclosure decisions.","correct":true,"id":"H"}],"answer":"Exports can disclose detail absent from the initial visual. A new audience can require different access and disclosure decisions. Actual behaviour should be checked rather than inferred from appearance. Technical publication success does not establish the required governance decision.","source":{"anchor":"ksb-s1","guideSha256":"572954ea98dd7ab0915240402eedd246d31250be6c5cd1f8f895c63a7f272b3a","excerpt":"Explain the systems you actually operated and the controls you personally applied throughout the work."},"id":"T26-E2-Q01"},{"ksb":"S1","objective":"Privacy by design","prompt":"You are designing a recurring dashboard before collecting data. Which actions embed privacy at this stage?","options":[{"text":"Retain every extract by default because it might help debugging","why":"Retention should reflect justified needs and applicable arrangements.","correct":false,"id":"A"},{"text":"Plan access restrictions for working data and outputs","why":"Personal working copies and intermediate stages also need appropriate controls.","correct":true,"id":"B"},{"text":"Protect only the final published report","why":"Personal working copies and intermediate stages also need appropriate controls.","correct":false,"id":"C"},{"text":"Define the minimum fields and intended users","why":"The purpose and necessary information should shape collection and design from the start.","correct":true,"id":"D"},{"text":"Assume aggregate presentation eliminates every identification risk","why":"Small groups and combinations can still create disclosure risks requiring assessment.","correct":false,"id":"E"},{"text":"Assess disclosure risks in the proposed outputs","why":"Small groups and combinations can still create disclosure risks requiring assessment.","correct":true,"id":"F"},{"text":"Collect all available fields and decide necessity after publication","why":"The purpose and necessary information should shape collection and design from the start.","correct":false,"id":"G"},{"text":"Agree retention and disposal arrangements","why":"Retention should reflect justified needs and applicable arrangements.","correct":true,"id":"H"}],"answer":"The purpose and necessary information should shape collection and design from the start. Personal working copies and intermediate stages also need appropriate controls. Retention should reflect justified needs and applicable arrangements. Small groups and combinations can still create disclosure risks requiring assessment.","source":{"anchor":"ksb-s1","guideSha256":"572954ea98dd7ab0915240402eedd246d31250be6c5cd1f8f895c63a7f272b3a","excerpt":"Explain the systems you actually operated and the controls you personally applied throughout the work."},"id":"T26-E2-Q02"},{"ksb":"S1","objective":"Access review evidence","prompt":"An assessor asks how you operated a system securely. Which evidence and explanation would demonstrate your own actions appropriately?","options":[{"text":"Reference suitably protected approval or query records","why":"A policy describes expected practice; suitable redacted records and explanation must also show how you actually operated within it.","correct":true,"id":"A"},{"text":"Claim a colleague's access review as your personal action","why":"Truthful attribution and actual controls provide stronger evidence than unsupported claims or lack of known incidents.","correct":false,"id":"B"},{"text":"List only the software's security marketing features","why":"Features do not establish how you actually applied controls to the task.","correct":false,"id":"C"},{"text":"Infer your compliance solely from the absence of a reported incident","why":"Truthful attribution and actual controls provide stronger evidence than unsupported claims or lack of known incidents.","correct":false,"id":"D"},{"text":"Use a generic system access-policy document as the sole evidence of your own compliant operation","why":"A policy describes expected practice; suitable redacted records and explanation must also show how you actually operated within it.","correct":false,"id":"E"},{"text":"Explain how selected fields matched the approved purpose","why":"Features do not establish how you actually applied controls to the task.","correct":true,"id":"F"},{"text":"Describe the role and controls used for the query","why":"The account should distinguish your operation from wider platform administration.","correct":true,"id":"G"},{"text":"Claim ownership of every platform security control","why":"The account should distinguish your operation from wider platform administration.","correct":false,"id":"H"}],"answer":"The account should distinguish your operation from wider platform administration. A policy describes expected practice; suitable redacted records and explanation must also show how you actually operated within it. Features do not establish how you actually applied controls to the task. Truthful attribution and actual controls provide stronger evidence than unsupported claims or lack of known incidents.","source":{"anchor":"ksb-s1","guideSha256":"572954ea98dd7ab0915240402eedd246d31250be6c5cd1f8f895c63a7f272b3a","excerpt":"Explain the systems you actually operated and the controls you personally applied throughout the work."},"id":"T26-E2-Q03"},{"ksb":"S1","objective":"Least-privilege extraction","prompt":"Your approved task needs aggregate service counts. The database offers a restricted view and a broad administrator account. Which operating choices fit the task?","options":[{"text":"Copy the source database locally to avoid access reviews","why":"Neither a speculative future use nor convenience justifies bypassing the agreed scope and controls.","correct":false,"id":"A"},{"text":"Query the authorised view containing the needed information","why":"The restricted view can meet the task without unnecessary privileges.","correct":true,"id":"B"},{"text":"Use the administrator account because it can access everything","why":"The restricted view can meet the task without unnecessary privileges.","correct":false,"id":"C"},{"text":"Publish the account credentials as evidence of permission","why":"An audit record should demonstrate authorised activity without disclosing authentication secrets.","correct":false,"id":"D"},{"text":"Keep a suitable record of the authorised extraction","why":"An audit record should demonstrate authorised activity without disclosing authentication secrets.","correct":true,"id":"E"},{"text":"Request all personal columns for unspecified future analysis","why":"Neither a speculative future use nor convenience justifies bypassing the agreed scope and controls.","correct":false,"id":"F"},{"text":"Verify the view's definitions and coverage","why":"Access controls and analytical suitability still need separate checks.","correct":true,"id":"G"},{"text":"Assume restricted access makes every measure suitable","why":"Access controls and analytical suitability still need separate checks.","correct":false,"id":"H"}],"answer":"The restricted view can meet the task without unnecessary privileges. Access controls and analytical suitability still need separate checks. An audit record should demonstrate authorised activity without disclosing authentication secrets. Neither a speculative future use nor convenience justifies bypassing the agreed scope and controls.","source":{"anchor":"ksb-s1","guideSha256":"572954ea98dd7ab0915240402eedd246d31250be6c5cd1f8f895c63a7f272b3a","excerpt":"Explain the systems you actually operated and the controls you personally applied throughout the work."},"id":"T26-E2-Q04"},{"ksb":"S1","objective":"Incident handling","prompt":"During an export you notice that an output contains more identifying fields than the approved scope. It has not yet been shared. Which actions are appropriate?","options":[{"text":"Send it because no unauthorised person has seen it yet","why":"Discovering excess detail before sharing is an opportunity to prevent unnecessary disclosure.","correct":false,"id":"A"},{"text":"Retain the unrestricted extract for informal troubleshooting","why":"Troubleshooting and conversion should remain within the approved handling environment.","correct":false,"id":"B"},{"text":"Use a public file converter to remove the extra fields","why":"Troubleshooting and conversion should remain within the approved handling environment.","correct":false,"id":"C"},{"text":"Stop the planned sharing and check the extract","why":"Discovering excess detail before sharing is an opportunity to prevent unnecessary disclosure.","correct":true,"id":"D"},{"text":"Correct the export through the authorised process","why":"Hidden columns can remain accessible and do not remove the underlying data.","correct":true,"id":"E"},{"text":"Follow the internal route for recording or escalating the issue as required","why":"Applicable internal processes still determine the appropriate record and response.","correct":true,"id":"F"},{"text":"Hide the columns in the workbook and assume they are removed","why":"Hidden columns can remain accessible and do not remove the underlying data.","correct":false,"id":"G"},{"text":"Conceal the mistake because it was caught before distribution","why":"Applicable internal processes still determine the appropriate record and response.","correct":false,"id":"H"}],"answer":"Discovering excess detail before sharing is an opportunity to prevent unnecessary disclosure. Hidden columns can remain accessible and do not remove the underlying data. Applicable internal processes still determine the appropriate record and response. Troubleshooting and conversion should remain within the approved handling environment.","source":{"anchor":"ksb-s1","guideSha256":"572954ea98dd7ab0915240402eedd246d31250be6c5cd1f8f895c63a7f272b3a","excerpt":"Explain the systems you actually operated and the controls you personally applied throughout the work."},"id":"T26-E2-Q05"},{"ksb":"S1","objective":"Screen sharing","prompt":"You need to demonstrate a dashboard during a meeting with attendees who lack access to individual records. Which actions support compliant operation?","options":[{"text":"Review only the opening screen","why":"Interactive controls can expose additional information during the demonstration.","correct":false,"id":"A"},{"text":"Keep credentials and sensitive notifications out of view","why":"Brief display can still expose information that should remain protected.","correct":true,"id":"B"},{"text":"Grant every attendee temporary source access to simplify the demonstration","why":"Unnecessary permissions and informal requests do not replace appropriate preparation and access controls.","correct":false,"id":"C"},{"text":"Rely solely on asking viewers not to remember identifying details","why":"Unnecessary permissions and informal requests do not replace appropriate preparation and access controls.","correct":false,"id":"D"},{"text":"Assume a live screen share is not a disclosure","why":"Showing records to unauthorised viewers can disclose information even without sending a file.","correct":false,"id":"E"},{"text":"Treat briefly visible authentication details as harmless","why":"Brief display can still expose information that should remain protected.","correct":false,"id":"F"},{"text":"Check drill-through and hidden detail that could appear","why":"Interactive controls can expose additional information during the demonstration.","correct":true,"id":"G"},{"text":"Use an appropriately sanitised or synthetic demonstration","why":"Showing records to unauthorised viewers can disclose information even without sending a file.","correct":true,"id":"H"}],"answer":"Showing records to unauthorised viewers can disclose information even without sending a file. Interactive controls can expose additional information during the demonstration. Brief display can still expose information that should remain protected. Unnecessary permissions and informal requests do not replace appropriate preparation and access controls.","source":{"anchor":"ksb-s1","guideSha256":"572954ea98dd7ab0915240402eedd246d31250be6c5cd1f8f895c63a7f272b3a","excerpt":"Explain the systems you actually operated and the controls you personally applied throughout the work."},"id":"T26-E2-Q06"},{"ksb":"S1","objective":"Pseudonymisation workflow","prompt":"Analysis requires linking repeated records for each person but does not require their names. Which implementation choices are justified?","options":[{"text":"Review only the removed name field for disclosure risk","why":"Other fields or combinations may still reveal identities.","correct":false,"id":"A"},{"text":"Assign a different unrelated identifier to every row and claim longitudinal linkage is preserved","why":"A consistent controlled linkage is needed to connect the relevant records over time.","correct":false,"id":"B"},{"text":"Put the mapping on the same broadly shared report tab","why":"Separating and restricting the mapping reduces unnecessary access to identities.","correct":false,"id":"C"},{"text":"Check indirect identifiers in proposed outputs","why":"Other fields or combinations may still reveal identities.","correct":true,"id":"D"},{"text":"Declare them anonymous merely because names are absent","why":"A usable re-identification mapping can leave the records as personal data.","correct":false,"id":"E"},{"text":"Use a suitable pseudonymous identifier for linkage","why":"A consistent controlled linkage is needed to connect the relevant records over time.","correct":true,"id":"F"},{"text":"Treat the linked records as potentially personal data","why":"A usable re-identification mapping can leave the records as personal data.","correct":true,"id":"G"},{"text":"Store the re-identification mapping under separate appropriate control","why":"Separating and restricting the mapping reduces unnecessary access to identities.","correct":true,"id":"H"}],"answer":"A consistent controlled linkage is needed to connect the relevant records over time. Separating and restricting the mapping reduces unnecessary access to identities. A usable re-identification mapping can leave the records as personal data. Other fields or combinations may still reveal identities.","source":{"anchor":"ksb-s1","guideSha256":"572954ea98dd7ab0915240402eedd246d31250be6c5cd1f8f895c63a7f272b3a","excerpt":"Explain the systems you actually operated and the controls you personally applied throughout the work."},"id":"T26-E2-Q07"},{"ksb":"S1","objective":"Scope expansion","prompt":"A dashboard originally used service totals. The sponsor now wants person-level drill-through. Which practical changes need assessment?","options":[{"text":"Review disclosure and audience permissions","why":"Permission for aggregate statistics does not necessarily permit access to underlying individuals.","correct":true,"id":"A"},{"text":"Keep the original risk account unchanged despite the new detail","why":"The project record should reflect material changes in processing and exposure.","correct":false,"id":"B"},{"text":"Add the feature first and rely on later complaints to identify risk","why":"Appropriate privacy and handling review should inform the changed design before use.","correct":false,"id":"C"},{"text":"Consult relevant responsible roles before implementation","why":"Appropriate privacy and handling review should inform the changed design before use.","correct":true,"id":"D"},{"text":"Reassess purpose, access and necessary detail","why":"Introducing person-level detail changes exposure and potentially the authorised use.","correct":true,"id":"E"},{"text":"Treat drill-through as purely visual styling","why":"Introducing person-level detail changes exposure and potentially the authorised use.","correct":false,"id":"F"},{"text":"Update the documented controls and retention decisions as needed","why":"The project record should reflect material changes in processing and exposure.","correct":true,"id":"G"},{"text":"Reuse the aggregate report's broad permissions automatically","why":"Permission for aggregate statistics does not necessarily permit access to underlying individuals.","correct":false,"id":"H"}],"answer":"Introducing person-level detail changes exposure and potentially the authorised use. Permission for aggregate statistics does not necessarily permit access to underlying individuals. Appropriate privacy and handling review should inform the changed design before use. The project record should reflect material changes in processing and exposure.","source":{"anchor":"ksb-s1","guideSha256":"572954ea98dd7ab0915240402eedd246d31250be6c5cd1f8f895c63a7f272b3a","excerpt":"Explain the systems you actually operated and the controls you personally applied throughout the work."},"id":"T26-E2-Q08"},{"ksb":"S1","objective":"Approved transfer","prompt":"A colleague requests an identifiable extract through personal email, while policy requires a managed transfer service. Which practical actions are appropriate?","options":[{"text":"Check that the colleague is entitled to the requested fields","why":"Authorisation depends on role and purpose, not just organisational membership.","correct":true,"id":"A"},{"text":"Send the full source because minimisation can happen after receipt","why":"Sending unnecessary fields expands exposure before any later reduction.","correct":false,"id":"B"},{"text":"Limit the extract to the agreed need","why":"Sending unnecessary fields expands exposure before any later reduction.","correct":true,"id":"C"},{"text":"Send through personal email after adding a password","why":"A password does not make the prohibited transfer route approved.","correct":false,"id":"D"},{"text":"Use the authorised transfer route for permitted recipients","why":"A password does not make the prohibited transfer route approved.","correct":true,"id":"E"},{"text":"Split the same restricted extract across several personal emails","why":"Expiry and splitting do not resolve the stated channel and access requirements.","correct":false,"id":"F"},{"text":"Upload to a consumer link service if the link expires quickly","why":"Expiry and splitting do not resolve the stated channel and access requirements.","correct":false,"id":"G"},{"text":"Treat employment in the same organisation as sufficient permission","why":"Authorisation depends on role and purpose, not just organisational membership.","correct":false,"id":"H"}],"answer":"A password does not make the prohibited transfer route approved. Authorisation depends on role and purpose, not just organisational membership. Sending unnecessary fields expands exposure before any later reduction. Expiry and splitting do not resolve the stated channel and access requirements.","source":{"anchor":"ksb-s1","guideSha256":"572954ea98dd7ab0915240402eedd246d31250be6c5cd1f8f895c63a7f272b3a","excerpt":"Explain the systems you actually operated and the controls you personally applied throughout the work."},"id":"T26-E2-Q09"},{"ksb":"S1","objective":"Working-copy retention","prompt":"Your analysis is complete and the working extract has reached its scheduled disposal date. Which actions implement the agreed controls?","options":[{"text":"Record completion or an authorised exception where required","why":"The record should accurately reflect the actual action and any approved exception.","correct":true,"id":"A"},{"text":"Delete only the desktop shortcut","why":"Removing a shortcut does not remove the underlying working data or other relevant copies.","correct":false,"id":"B"},{"text":"Retain all personal records merely to prove a query once ran","why":"Appropriate methods and audit material can support explanation without automatically retaining all identifiable inputs.","correct":false,"id":"C"},{"text":"Consider approved shared copies as well as local files","why":"Removing a shortcut does not remove the underlying working data or other relevant copies.","correct":true,"id":"D"},{"text":"Describe an unapproved delay as completed disposal","why":"The record should accurately reflect the actual action and any approved exception.","correct":false,"id":"E"},{"text":"Follow the approved deletion or retention-review process","why":"Usefulness alone does not establish an authorised continuing retention need.","correct":true,"id":"F"},{"text":"Keep the extract indefinitely because the final answer was useful","why":"Usefulness alone does not establish an authorised continuing retention need.","correct":false,"id":"G"},{"text":"Preserve suitable permitted methodological records","why":"Appropriate methods and audit material can support explanation without automatically retaining all identifiable inputs.","correct":true,"id":"H"}],"answer":"Usefulness alone does not establish an authorised continuing retention need. Removing a shortcut does not remove the underlying working data or other relevant copies. Appropriate methods and audit material can support explanation without automatically retaining all identifiable inputs. The record should accurately reflect the actual action and any approved exception.","source":{"anchor":"ksb-s1","guideSha256":"572954ea98dd7ab0915240402eedd246d31250be6c5cd1f8f895c63a7f272b3a","excerpt":"Explain the systems you actually operated and the controls you personally applied throughout the work."},"id":"T26-E2-Q10"}]},{"id":"T27","title":"S2 · Applying the Data Analysis Lifecycle","description":"Actual planning, preparation, analysis, refinement and handover.","questions":[{"ksb":"S2","objective":"Analysis evidence","prompt":"A project compares delay distributions between two services. Which account demonstrates your analysis rather than simply naming tools?","options":[{"text":"Explain the summaries and comparisons you performed","why":"A method account identifies the analytical operations, not just available software.","correct":true,"id":"A"},{"text":"State only that Excel and Python were installed","why":"A method account identifies the analytical operations, not just available software.","correct":false,"id":"B"},{"text":"Claim an unused regression model to make the project look advanced","why":"The account should describe methods actually applied and distinguish acquisition from inference.","correct":false,"id":"C"},{"text":"Justify the method using the question and data characteristics","why":"A defensible choice follows the question, design and assumptions.","correct":true,"id":"D"},{"text":"Say the method was chosen because it produced the preferred result","why":"A defensible choice follows the question, design and assumptions.","correct":false,"id":"E"},{"text":"Interpret the results with relevant uncertainty and limits","why":"Practical analysis includes interpretation, not merely generating output.","correct":true,"id":"F"},{"text":"Paste numerical output without explaining its business meaning","why":"Practical analysis includes interpretation, not merely generating output.","correct":false,"id":"G"},{"text":"Treat a data import as evidence that inferential testing occurred","why":"The account should describe methods actually applied and distinguish acquisition from inference.","correct":false,"id":"H"}],"answer":"A method account identifies the analytical operations, not just available software. A defensible choice follows the question, design and assumptions. Practical analysis includes interpretation, not merely generating output. The account should describe methods actually applied and distinguish acquisition from inference.","source":{"anchor":"ksb-s2","guideSha256":"1e42a8017fc0a22b3438b81346ad97e890b7b11194c4f4c8cfda20694ed98079","excerpt":"K3 explains the lifecycle; S2 shows that you carried it out."},"id":"T27-E2-Q01"},{"ksb":"S2","objective":"Changed data availability","prompt":"A planned comparison source becomes unavailable through the approved route. Which practical lifecycle response is appropriate?","options":[{"text":"Use an unapproved copy to preserve the original plan","why":"An analytical plan must remain within authorised data access.","correct":false,"id":"A"},{"text":"Assume a similarly named dataset is equivalent","why":"An alternative needs checks of meaning, coverage and fitness.","correct":false,"id":"B"},{"text":"Update methods, validation and communication to reflect the actual input","why":"The account must match the data and analysis actually used.","correct":true,"id":"C"},{"text":"Keep the original methods section unchanged","why":"The account must match the data and analysis actually used.","correct":false,"id":"D"},{"text":"State that no preparation occurred because the first source was unavailable","why":"Changed availability does not justify omitting actual work or inventing completed analysis.","correct":false,"id":"E"},{"text":"Evaluate a suitable alternative and its limitations","why":"An alternative needs checks of meaning, coverage and fitness.","correct":true,"id":"F"},{"text":"Claim the original comparison was completed using hypothetical values","why":"Changed availability does not justify omitting actual work or inventing completed analysis.","correct":false,"id":"G"},{"text":"Reassess feasibility and agree a revised scope if needed","why":"An analytical plan must remain within authorised data access.","correct":true,"id":"H"}],"answer":"An analytical plan must remain within authorised data access. An alternative needs checks of meaning, coverage and fitness. The account must match the data and analysis actually used. Changed availability does not justify omitting actual work or inventing completed analysis.","source":{"anchor":"ksb-s2","guideSha256":"1e42a8017fc0a22b3438b81346ad97e890b7b11194c4f4c8cfda20694ed98079","excerpt":"K3 explains the lifecycle; S2 shows that you carried it out."},"id":"T27-E2-Q02"},{"ksb":"S2","objective":"Planning artefact","prompt":"Your project begins with a request to explain delayed cases. Which actions provide practical planning evidence?","options":[{"text":"Treat the final presentation date as the entire plan","why":"A deadline alone does not define the activities and acceptance criteria needed to deliver.","correct":false,"id":"A"},{"text":"Start creating charts without confirming what delay means","why":"A clear brief connects subsequent work to the actual business question.","correct":false,"id":"B"},{"text":"Use a final deliverable list as the entire planning record, without the original decision or constraints","why":"Planning evidence should explain the actual decision, scope and constraints that shaped the work, not infer all planning from what was eventually delivered.","correct":false,"id":"C"},{"text":"Identify access, risks and responsible stakeholders","why":"Feasibility depends on authorised access and relevant responsibilities.","correct":true,"id":"D"},{"text":"Record success criteria and a realistic sequence of work","why":"A deadline alone does not define the activities and acceptance criteria needed to deliver.","correct":true,"id":"E"},{"text":"Agree the question, population and delivery scope","why":"A clear brief connects subsequent work to the actual business question.","correct":true,"id":"F"},{"text":"Assume available data has no access dependencies","why":"Feasibility depends on authorised access and relevant responsibilities.","correct":false,"id":"G"},{"text":"Attribute the sponsor's decisions to your own independent work","why":"Planning evidence should explain the actual decision, scope and constraints that shaped the work, not infer all planning from what was eventually delivered.","correct":false,"id":"H"}],"answer":"A clear brief connects subsequent work to the actual business question. Feasibility depends on authorised access and relevant responsibilities. A deadline alone does not define the activities and acceptance criteria needed to deliver. Planning evidence should explain the actual decision, scope and constraints that shaped the work, not infer all planning from what was eventually delivered.","source":{"anchor":"ksb-s2","guideSha256":"1e42a8017fc0a22b3438b81346ad97e890b7b11194c4f4c8cfda20694ed98079","excerpt":"K3 explains the lifecycle; S2 shows that you carried it out."},"id":"T27-E2-Q03"},{"ksb":"S2","objective":"Validation evidence","prompt":"After analysis, you find that one dashboard total differs from the source total. Which actions demonstrate refining and comparing?","options":[{"text":"Accept the first plausible explanation without verification","why":"A plausible explanation needs evidence before it supports correction.","correct":false,"id":"A"},{"text":"Reconcile the populations and transformations behind both totals","why":"Reconciliation investigates why figures differ rather than forcing a desired appearance.","correct":true,"id":"B"},{"text":"Test the suspected cause and rerun relevant checks","why":"A plausible explanation needs evidence before it supports correction.","correct":true,"id":"C"},{"text":"Document any justified revision and its effect","why":"A traceable revision explains how validation improved the analysis.","correct":true,"id":"D"},{"text":"Describe an untested alternative as demonstrably superior","why":"A comparison should distinguish observed evidence from an untested proposal.","correct":false,"id":"E"},{"text":"Delete the earlier result and omit the reason for the change","why":"A traceable revision explains how validation improved the analysis.","correct":false,"id":"F"},{"text":"Compare a feasible alternative where useful","why":"A comparison should distinguish observed evidence from an untested proposal.","correct":true,"id":"G"},{"text":"Change the dashboard number manually to match the source headline","why":"Reconciliation investigates why figures differ rather than forcing a desired appearance.","correct":false,"id":"H"}],"answer":"Reconciliation investigates why figures differ rather than forcing a desired appearance. A plausible explanation needs evidence before it supports correction. A traceable revision explains how validation improved the analysis. A comparison should distinguish observed evidence from an untested proposal.","source":{"anchor":"ksb-s2","guideSha256":"1e42a8017fc0a22b3438b81346ad97e890b7b11194c4f4c8cfda20694ed98079","excerpt":"K3 explains the lifecycle; S2 shows that you carried it out."},"id":"T27-E2-Q04"},{"ksb":"S2","objective":"Lifecycle traceability","prompt":"Your portfolio contains several useful artefacts, but the assessor cannot see how they connect. Which improvements make the project account coherent?","options":[{"text":"Link the agreed requirement to the method and output","why":"The account should show how the analytical work answered the planned question.","correct":true,"id":"A"},{"text":"Treat the existence of a handover document as proof that every earlier lifecycle stage was completed","why":"A coherent account connects actual actions and artefacts to each stage. Missing evidence should be identified rather than inferred from a later document.","correct":false,"id":"B"},{"text":"Treat cleaning as an unrelated administrative task","why":"Preparation shapes which observations and meanings enter the analysis.","correct":false,"id":"C"},{"text":"State that all stages happened without explaining any actions","why":"A continuous account needs actual decisions and outcomes, not only stage labels.","correct":false,"id":"D"},{"text":"Fill missing stages with invented activities","why":"A coherent account connects actual actions and artefacts to each stage. Missing evidence should be identified rather than inferred from a later document.","correct":false,"id":"E"},{"text":"Explain how preparation decisions affected the analysis","why":"Preparation shapes which observations and meanings enter the analysis.","correct":true,"id":"F"},{"text":"Connect validation findings to revisions and handover","why":"A continuous account needs actual decisions and outcomes, not only stage labels.","correct":true,"id":"G"},{"text":"Arrange files only by software name","why":"The account should show how the analytical work answered the planned question.","correct":false,"id":"H"}],"answer":"The account should show how the analytical work answered the planned question. Preparation shapes which observations and meanings enter the analysis. A continuous account needs actual decisions and outcomes, not only stage labels. A coherent account connects actual actions and artefacts to each stage. Missing evidence should be identified rather than inferred from a later document.","source":{"anchor":"ksb-s2","guideSha256":"1e42a8017fc0a22b3438b81346ad97e890b7b11194c4f4c8cfda20694ed98079","excerpt":"K3 explains the lifecycle; S2 shows that you carried it out."},"id":"T27-E2-Q05"},{"ksb":"S2","objective":"Post-handover review","prompt":"The team reports that your analysis is useful but the refresh process is too slow for their meeting. Which actions complete a reflective lifecycle account?","options":[{"text":"Report a proposed refresh as a verified outcome","why":"Plans and completed, checked changes should remain clearly separated.","correct":false,"id":"A"},{"text":"Gather specific feedback about the timing need","why":"A useful output can still have an unmet operational constraint.","correct":true,"id":"B"},{"text":"Infer that usefulness means every requirement was satisfied","why":"A useful output can still have an unmet operational constraint.","correct":false,"id":"C"},{"text":"Record the lesson for future planning and handover","why":"Learning from use can improve future analytical projects.","correct":true,"id":"D"},{"text":"Promise a faster source update without checking dependencies","why":"A sustainable improvement needs appropriate authority and technical feasibility.","correct":false,"id":"E"},{"text":"Investigate feasible refresh improvements with the relevant owner","why":"A sustainable improvement needs appropriate authority and technical feasibility.","correct":true,"id":"F"},{"text":"Distinguish an agreed improvement from one already deployed","why":"Plans and completed, checked changes should remain clearly separated.","correct":true,"id":"G"},{"text":"Treat implementation feedback as unrelated to analysis","why":"Learning from use can improve future analytical projects.","correct":false,"id":"H"}],"answer":"A useful output can still have an unmet operational constraint. A sustainable improvement needs appropriate authority and technical feasibility. Learning from use can improve future analytical projects. Plans and completed, checked changes should remain clearly separated.","source":{"anchor":"ksb-s2","guideSha256":"1e42a8017fc0a22b3438b81346ad97e890b7b11194c4f4c8cfda20694ed98079","excerpt":"K3 explains the lifecycle; S2 shows that you carried it out."},"id":"T27-E2-Q06"},{"ksb":"S2","objective":"Responsibility boundaries","prompt":"A data engineer supplies a cleaned table, and you perform analysis, validation and communication. Which explanation is accurate?","options":[{"text":"Describe every upstream transformation as your own work","why":"The project narrative should distinguish individual and collaborative contributions.","correct":false,"id":"A"},{"text":"Attribute the supplied cleaning to the engineer","why":"The project narrative should distinguish individual and collaborative contributions.","correct":true,"id":"B"},{"text":"Assume supplied data requires no suitability checks","why":"You still need to assess whether the input is fit for your analytical purpose.","correct":false,"id":"C"},{"text":"Explain the quality checks you performed on the supplied data","why":"You still need to assess whether the input is fit for your analytical purpose.","correct":true,"id":"D"},{"text":"Claim reading a cleaning log proves you personally executed its steps","why":"Understanding another person's work is different from demonstrating your own execution.","correct":false,"id":"E"},{"text":"Omit dependencies to make the work appear wholly independent","why":"Understanding and coordinating dependencies is part of a truthful account.","correct":false,"id":"F"},{"text":"Identify any evidence gap in your own lifecycle application","why":"Understanding another person's work is different from demonstrating your own execution.","correct":true,"id":"G"},{"text":"Describe how you clarified preparation decisions with the engineer","why":"Understanding and coordinating dependencies is part of a truthful account.","correct":true,"id":"H"}],"answer":"The project narrative should distinguish individual and collaborative contributions. You still need to assess whether the input is fit for your analytical purpose. Understanding and coordinating dependencies is part of a truthful account. Understanding another person's work is different from demonstrating your own execution.","source":{"anchor":"ksb-s2","guideSha256":"1e42a8017fc0a22b3438b81346ad97e890b7b11194c4f4c8cfda20694ed98079","excerpt":"K3 explains the lifecycle; S2 shows that you carried it out."},"id":"T27-E2-Q07"},{"ksb":"S2","objective":"Iterative project","prompt":"A stakeholder review changes the agreed case definition, requiring recalculation. Which account demonstrates practical lifecycle application?","options":[{"text":"Change only the heading while retaining the old values","why":"A changed definition can require changes in data preparation and analysis.","correct":false,"id":"A"},{"text":"Revalidate and communicate the revised output","why":"Validation needs to cover the revised method and result.","correct":true,"id":"B"},{"text":"Explain the effect of the change on scope and interpretation","why":"Changed definitions can affect comparability and should be explained.","correct":true,"id":"C"},{"text":"Rely entirely on checks of the earlier calculation","why":"Validation needs to cover the revised method and result.","correct":false,"id":"D"},{"text":"Describe why planning and preparation were revisited","why":"A truthful iterative account can show responsive analytical work.","correct":true,"id":"E"},{"text":"Implement the confirmed definition in the affected calculations","why":"A changed definition can require changes in data preparation and analysis.","correct":true,"id":"F"},{"text":"Present the earlier and later results as directly comparable without qualification","why":"Changed definitions can affect comparability and should be explained.","correct":false,"id":"G"},{"text":"Hide the iteration to suggest every stage happened only once","why":"A truthful iterative account can show responsive analytical work.","correct":false,"id":"H"}],"answer":"A truthful iterative account can show responsive analytical work. A changed definition can require changes in data preparation and analysis. Validation needs to cover the revised method and result. Changed definitions can affect comparability and should be explained.","source":{"anchor":"ksb-s2","guideSha256":"1e42a8017fc0a22b3438b81346ad97e890b7b11194c4f4c8cfda20694ed98079","excerpt":"K3 explains the lifecycle; S2 shows that you carried it out."},"id":"T27-E2-Q08"},{"ksb":"S2","objective":"Preparation evidence","prompt":"You standardise dates, investigate missing statuses and combine two authorised sources. Which records demonstrate this lifecycle stage?","options":[{"text":"List extra sources that were considered but never used as integrated inputs","why":"The evidence should distinguish actual inputs from alternatives or references.","correct":false,"id":"A"},{"text":"References to the actual authorised sources","why":"The evidence should distinguish actual inputs from alternatives or references.","correct":true,"id":"B"},{"text":"A transformation log explaining the applied rules","why":"The log shows what preparation occurred and why, rather than only the later output.","correct":true,"id":"C"},{"text":"Only a screenshot of the final chart","why":"The log shows what preparation occurred and why, rather than only the later output.","correct":false,"id":"D"},{"text":"Before-and-after counts and identified exceptions","why":"Practical checks support the transformation more directly than the tool name.","correct":true,"id":"E"},{"text":"Replace unknown values and omit the assumptions","why":"Unresolved information needs justified treatment and transparent limits.","correct":false,"id":"F"},{"text":"A reasoned treatment of unresolved missing values","why":"Unresolved information needs justified treatment and transparent limits.","correct":true,"id":"G"},{"text":"A claim that using Power Query proves cleaning was correct","why":"Practical checks support the transformation more directly than the tool name.","correct":false,"id":"H"}],"answer":"The log shows what preparation occurred and why, rather than only the later output. Practical checks support the transformation more directly than the tool name. Unresolved information needs justified treatment and transparent limits. The evidence should distinguish actual inputs from alternatives or references.","source":{"anchor":"ksb-s2","guideSha256":"1e42a8017fc0a22b3438b81346ad97e890b7b11194c4f4c8cfda20694ed98079","excerpt":"K3 explains the lifecycle; S2 shows that you carried it out."},"id":"T27-E2-Q09"},{"ksb":"S2","objective":"Communication evidence","prompt":"You present a completed analysis to a service manager and provide a handover note. Which details show the final lifecycle stage?","options":[{"text":"Record agreed next actions and responsibility where relevant","why":"Sending a result does not prove adoption or implementation.","correct":true,"id":"A"},{"text":"Claim the recommendation was implemented solely because you sent it","why":"Sending a result does not prove adoption or implementation.","correct":false,"id":"B"},{"text":"Explain the decision-relevant findings and limitations","why":"The audience needs an understandable account of implications and limitations.","correct":true,"id":"C"},{"text":"Supply only the raw query output","why":"The audience needs an understandable account of implications and limitations.","correct":false,"id":"D"},{"text":"Assume every audience needs the same technical detail","why":"Communication should suit the recipient's task and understanding.","correct":false,"id":"E"},{"text":"Claim feedback from a meeting you did not attend","why":"Evidence needs to reflect actual communication and genuine observations.","correct":false,"id":"F"},{"text":"Count a saved slide deck as evidence that a discussion occurred","why":"Evidence needs to reflect actual communication and genuine observations.","correct":false,"id":"G"},{"text":"Describe audience-specific presentation choices","why":"Communication should suit the recipient's task and understanding.","correct":true,"id":"H"}],"answer":"The audience needs an understandable account of implications and limitations. Communication should suit the recipient's task and understanding. Sending a result does not prove adoption or implementation. Evidence needs to reflect actual communication and genuine observations.","source":{"anchor":"ksb-s2","guideSha256":"1e42a8017fc0a22b3438b81346ad97e890b7b11194c4f4c8cfda20694ed98079","excerpt":"K3 explains the lifecycle; S2 shows that you carried it out."},"id":"T27-E2-Q10"}]},{"id":"T28","title":"S3 · Applying Principles of Data Classification","description":"Classification decisions, authorised treatment and remaining identification risks.","questions":[{"ksb":"S3","objective":"Context changes risk","prompt":"A detailed internal dataset is proposed for an external presentation. Which classification actions are appropriate?","options":[{"text":"Let the presenter privately lower the sensitivity label","why":"A change in classification or handling needs the appropriate authority.","correct":false,"id":"A"},{"text":"Reassess the audience and proposed release detail","why":"A different audience can change both permissions and disclosure risk.","correct":true,"id":"B"},{"text":"Check whether a safer summary meets the presentation purpose","why":"An earlier classification does not automatically authorise every later distribution.","correct":true,"id":"C"},{"text":"Treat the public presentation title as proof the dataset is public","why":"The intended event does not determine the source data's permitted handling.","correct":false,"id":"D"},{"text":"Seek the relevant approval for any changed treatment","why":"A change in classification or handling needs the appropriate authority.","correct":true,"id":"E"},{"text":"Record the rationale and remaining restrictions","why":"The intended event does not determine the source data's permitted handling.","correct":true,"id":"F"},{"text":"Reuse the internal sharing decision without review","why":"A different audience can change both permissions and disclosure risk.","correct":false,"id":"G"},{"text":"Send the full internal file because it was already classified once","why":"An earlier classification does not automatically authorise every later distribution.","correct":false,"id":"H"}],"answer":"A different audience can change both permissions and disclosure risk. An earlier classification does not automatically authorise every later distribution. A change in classification or handling needs the appropriate authority. The intended event does not determine the source data's permitted handling.","source":{"anchor":"ksb-s3","guideSha256":"6e7245ee3fe6dc9da12b01ab547600adaa1bbf9400a7ecf58a49c2ba5d8fe83f","excerpt":"Assess sensitivity, identifiability, purpose, access and potential harm, then apply your organisation's real classification and handling scheme."},"id":"T28-E2-Q01"},{"ksb":"S3","objective":"Qualitative to quantitative","prompt":"You code confidential comments into themes for a wider report. Which account of the treatment is sound?","options":[{"text":"Claim theme counts preserve every nuance of the original comments","why":"Coding creates a summary and can lose context or ambiguity.","correct":false,"id":"A"},{"text":"Present coded categories as directly observed numerical measurements","why":"Themes are derived interpretations and should be described accordingly.","correct":false,"id":"B"},{"text":"Explain the purpose and limitations of the transformed output","why":"Themes are derived interpretations and should be described accordingly.","correct":true,"id":"C"},{"text":"Retain raw comments only within authorised access and retention arrangements","why":"Verification should not unnecessarily expand access to sensitive source material.","correct":true,"id":"D"},{"text":"Review rare themes and combinations for disclosure risk","why":"A rare category can still reveal sensitive information in context.","correct":true,"id":"E"},{"text":"Share the raw comments with every reader to prove the counts","why":"Verification should not unnecessarily expand access to sensitive source material.","correct":false,"id":"F"},{"text":"Explain how themes were defined and counted","why":"Coding creates a summary and can lose context or ambiguity.","correct":true,"id":"G"},{"text":"Assume omission of direct quotations settles confidentiality","why":"A rare category can still reveal sensitive information in context.","correct":false,"id":"H"}],"answer":"Coding creates a summary and can lose context or ambiguity. A rare category can still reveal sensitive information in context. Verification should not unnecessarily expand access to sensitive source material. Themes are derived interpretations and should be described accordingly.","source":{"anchor":"ksb-s3","guideSha256":"6e7245ee3fe6dc9da12b01ab547600adaa1bbf9400a7ecf58a49c2ba5d8fe83f","excerpt":"Assess sensitivity, identifiability, purpose, access and potential harm, then apply your organisation's real classification and handling scheme."},"id":"T28-E2-Q02"},{"ksb":"S3","objective":"Uncertain sensitivity","prompt":"A new file contains unfamiliar codes that may link to individuals. Documentation is incomplete. Which next actions are justified?","options":[{"text":"Assume every unknown code is highly sensitive without checking its meaning","why":"Cosmetic changes do not resolve identifiability, and final classification should follow a reasoned assessment.","correct":false,"id":"A"},{"text":"Clarify the codes with the responsible owner","why":"A code can identify or link people even if its meaning is unfamiliar to the analyst.","correct":true,"id":"B"},{"text":"Publish first because the codes contain no names","why":"Uncertainty about identification is a reason to investigate, not proof that disclosure is safe.","correct":false,"id":"C"},{"text":"Treat unreadable codes as anonymous by default","why":"A code can identify or link people even if its meaning is unfamiliar to the analyst.","correct":false,"id":"D"},{"text":"Restrict use and sharing appropriately while uncertainty is resolved","why":"Uncertainty about identification is a reason to investigate, not proof that disclosure is safe.","correct":true,"id":"E"},{"text":"Replace the codes with shorter ones and declare the issue solved","why":"Cosmetic changes do not resolve identifiability, and final classification should follow a reasoned assessment.","correct":false,"id":"F"},{"text":"Record the confirmed classification and handling decision","why":"The decision needs information about the actual contents and applicable rules.","correct":true,"id":"G"},{"text":"Infer sensitivity solely from the sender's job title","why":"The decision needs information about the actual contents and applicable rules.","correct":false,"id":"H"}],"answer":"A code can identify or link people even if its meaning is unfamiliar to the analyst. Uncertainty about identification is a reason to investigate, not proof that disclosure is safe. The decision needs information about the actual contents and applicable rules. Cosmetic changes do not resolve identifiability, and final classification should follow a reasoned assessment.","source":{"anchor":"ksb-s3","guideSha256":"6e7245ee3fe6dc9da12b01ab547600adaa1bbf9400a7ecf58a49c2ba5d8fe83f","excerpt":"Assess sensitivity, identifiability, purpose, access and potential harm, then apply your organisation's real classification and handling scheme."},"id":"T28-E2-Q03"},{"ksb":"S3","objective":"Small-group counts","prompt":"You replace sensitive narrative cases with category counts. One category contains only one person. Which conclusions follow?","options":[{"text":"Judge safety only by whether the value is numeric","why":"Risk depends on meaning and context rather than the data type alone.","correct":false,"id":"A"},{"text":"Converting text to numbers guarantees safe publication","why":"Aggregation does not automatically remove small-group or linkage risks.","correct":false,"id":"B"},{"text":"Change the count from one to three and present it as observed","why":"Disclosure treatment should not silently fabricate observed values.","correct":false,"id":"C"},{"text":"Consider suitable suppression or broader grouping","why":"Disclosure treatment should not silently fabricate observed values.","correct":true,"id":"D"},{"text":"Treat every count table as a low-risk dataset","why":"Counts and category labels can still communicate sensitive facts about identifiable groups or individuals.","correct":false,"id":"E"},{"text":"Infer that a category label cannot reveal sensitive information","why":"Counts and category labels can still communicate sensitive facts about identifiable groups or individuals.","correct":false,"id":"F"},{"text":"Counts can still expose a rare individual in context","why":"Aggregation does not automatically remove small-group or linkage risks.","correct":true,"id":"G"},{"text":"Review the category and audience before release","why":"Risk depends on meaning and context rather than the data type alone.","correct":true,"id":"H"}],"answer":"Aggregation does not automatically remove small-group or linkage risks. Risk depends on meaning and context rather than the data type alone. Disclosure treatment should not silently fabricate observed values. Counts and category labels can still communicate sensitive facts about identifiable groups or individuals.","source":{"anchor":"ksb-s3","guideSha256":"6e7245ee3fe6dc9da12b01ab547600adaa1bbf9400a7ecf58a49c2ba5d8fe83f","excerpt":"Assess sensitivity, identifiability, purpose, access and potential harm, then apply your organisation's real classification and handling scheme."},"id":"T28-E2-Q04"},{"ksb":"S3","objective":"Classification evidence","prompt":"An assessor asks why you classified a project extract as restricted. Which explanation demonstrates reasoned application?","options":[{"text":"Substitute an invented universal classification scale","why":"The explanation should use the scheme that actually governed the work.","correct":false,"id":"A"},{"text":"Describe the resulting access and sharing controls","why":"The practical consequences demonstrate how classification affected handling.","correct":true,"id":"B"},{"text":"Lower the classification because the extract has fewer rows than the original","why":"A smaller file can still contain identifying or sensitive information; explain content, context and handling requirements rather than infer risk from size or naming.","correct":false,"id":"C"},{"text":"Say only that all company data is restricted","why":"A reasoned decision connects the label to this dataset and its context.","correct":false,"id":"D"},{"text":"Identify the actual sensitive fields and potential harm","why":"A reasoned decision connects the label to this dataset and its context.","correct":true,"id":"E"},{"text":"Infer low risk from the small file size","why":"A smaller file can still contain identifying or sensitive information; explain content, context and handling requirements rather than infer risk from size or naming.","correct":false,"id":"F"},{"text":"Explain the applicable organisational criteria","why":"The explanation should use the scheme that actually governed the work.","correct":true,"id":"G"},{"text":"Treat the label alone as evidence controls were applied","why":"The practical consequences demonstrate how classification affected handling.","correct":false,"id":"H"}],"answer":"A reasoned decision connects the label to this dataset and its context. The explanation should use the scheme that actually governed the work. The practical consequences demonstrate how classification affected handling. A smaller file can still contain identifying or sensitive information; explain content, context and handling requirements rather than infer risk from size or naming.","source":{"anchor":"ksb-s3","guideSha256":"6e7245ee3fe6dc9da12b01ab547600adaa1bbf9400a7ecf58a49c2ba5d8fe83f","excerpt":"Assess sensitivity, identifiability, purpose, access and potential harm, then apply your organisation's real classification and handling scheme."},"id":"T28-E2-Q05"},{"ksb":"S3","objective":"Pseudonymisation control","prompt":"You need consistent person-level linkage across two extracts. Which handling decisions are justified?","options":[{"text":"Use an approved consistent pseudonymisation approach","why":"Unrelated row numbers do not establish that records concern the same individual.","correct":true,"id":"A"},{"text":"Automatically downgrade it to public because direct names are gone","why":"Pseudonymisation can leave personal information requiring controls.","correct":false,"id":"B"},{"text":"Assign unrelated row numbers in each file and assume they link people","why":"Unrelated row numbers do not establish that records concern the same individual.","correct":false,"id":"C"},{"text":"Share the lookup with everyone who receives summary charts","why":"Broad lookup access defeats the intended separation of identity from analysis.","correct":false,"id":"D"},{"text":"Document the purpose and limitations of the treatment","why":"The technique reduces some risks without eliminating all disclosure considerations.","correct":true,"id":"E"},{"text":"Control access to any re-identification lookup","why":"Broad lookup access defeats the intended separation of identity from analysis.","correct":true,"id":"F"},{"text":"Treat the transformed data according to its residual identifiability","why":"Pseudonymisation can leave personal information requiring controls.","correct":true,"id":"G"},{"text":"Describe pseudonymisation as proof that disclosure checks are unnecessary","why":"The technique reduces some risks without eliminating all disclosure considerations.","correct":false,"id":"H"}],"answer":"Unrelated row numbers do not establish that records concern the same individual. Broad lookup access defeats the intended separation of identity from analysis. Pseudonymisation can leave personal information requiring controls. The technique reduces some risks without eliminating all disclosure considerations.","source":{"anchor":"ksb-s3","guideSha256":"6e7245ee3fe6dc9da12b01ab547600adaa1bbf9400a7ecf58a49c2ba5d8fe83f","excerpt":"Assess sensitivity, identifiability, purpose, access and potential harm, then apply your organisation's real classification and handling scheme."},"id":"T28-E2-Q06"},{"ksb":"S3","objective":"Residual risk explanation","prompt":"A permitted output uses broader age bands and regional totals instead of exact ages and addresses. Which explanation is accurate?","options":[{"text":"Record why the treatment was approved for this audience","why":"Permission and risk are tied to the assessed use and recipients.","correct":true,"id":"A"},{"text":"Describe a pseudonymous source as inherently non-personal","why":"A safer output does not automatically change the source's identifiability or eliminate every risk.","correct":false,"id":"B"},{"text":"Treat approval for one audience as unlimited future release permission","why":"Permission and risk are tied to the assessed use and recipients.","correct":false,"id":"C"},{"text":"Describe the disclosure checks still performed","why":"Group sizes and contextual linkage can remain relevant after aggregation.","correct":true,"id":"D"},{"text":"Claim aggregation improves every possible analytical use","why":"Reduced detail can lower risk while limiting some analyses.","correct":false,"id":"E"},{"text":"Distinguish risk reduction from a guarantee of zero risk","why":"A safer output does not automatically change the source's identifiability or eliminate every risk.","correct":true,"id":"F"},{"text":"State that coarser categories make all checking redundant","why":"Group sizes and contextual linkage can remain relevant after aggregation.","correct":false,"id":"G"},{"text":"Explain how reduced detail serves the agreed purpose","why":"Reduced detail can lower risk while limiting some analyses.","correct":true,"id":"H"}],"answer":"Reduced detail can lower risk while limiting some analyses. Group sizes and contextual linkage can remain relevant after aggregation. Permission and risk are tied to the assessed use and recipients. A safer output does not automatically change the source's identifiability or eliminate every risk.","source":{"anchor":"ksb-s3","guideSha256":"6e7245ee3fe6dc9da12b01ab547600adaa1bbf9400a7ecf58a49c2ba5d8fe83f","excerpt":"Assess sensitivity, identifiability, purpose, access and potential harm, then apply your organisation's real classification and handling scheme."},"id":"T28-E2-Q07"},{"ksb":"S3","objective":"Applying local labels","prompt":"Your organisation uses Official and Restricted labels, while a course example uses low, medium and high risk. Which classification approach is appropriate?","options":[{"text":"Infer the permitted audience from the spreadsheet's colour theme","why":"Data origin and appearance do not establish a context-specific handling decision.","correct":false,"id":"A"},{"text":"Link the label to the controls actually required","why":"Risk descriptions and local classification labels need a reasoned mapping to the organisation's actual access, sharing and storage controls.","correct":true,"id":"B"},{"text":"Apply the organisation's actual handling scheme","why":"Course categories do not override the organisation's defined scheme.","correct":true,"id":"C"},{"text":"Choose a label solely from the file extension","why":"Classification depends on content and context, not just storage format.","correct":false,"id":"D"},{"text":"Replace the approved labels with the course's example labels","why":"Course categories do not override the organisation's defined scheme.","correct":false,"id":"E"},{"text":"Assume every administrative dataset has the same sensitivity","why":"Data origin and appearance do not establish a context-specific handling decision.","correct":false,"id":"F"},{"text":"Explain the sensitivity and reasoning behind the assigned label","why":"Classification depends on content and context, not just storage format.","correct":true,"id":"G"},{"text":"Apply the course's risk label directly as a sharing permission without checking local handling rules","why":"Risk descriptions and local classification labels need a reasoned mapping to the organisation's actual access, sharing and storage controls.","correct":false,"id":"H"}],"answer":"Course categories do not override the organisation's defined scheme. Classification depends on content and context, not just storage format. Risk descriptions and local classification labels need a reasoned mapping to the organisation's actual access, sharing and storage controls. Data origin and appearance do not establish a context-specific handling decision.","source":{"anchor":"ksb-s3","guideSha256":"6e7245ee3fe6dc9da12b01ab547600adaa1bbf9400a7ecf58a49c2ba5d8fe83f","excerpt":"Assess sensitivity, identifiability, purpose, access and potential harm, then apply your organisation's real classification and handling scheme."},"id":"T28-E2-Q08"},{"ksb":"S3","objective":"Redacting evidence","prompt":"A workplace screenshot contains useful analytical evidence and confidential names. Which preparation supports safe portfolio use?","options":[{"text":"Assume assessment use automatically permits every workplace disclosure","why":"The portfolio purpose does not remove the organisation's handling rules.","correct":false,"id":"A"},{"text":"Publish the unredacted file alongside the redacted copy for comparison","why":"Fabricated evidence and an exposed original undermine the purpose of safe redaction.","correct":false,"id":"B"},{"text":"Preserve enough analytical context to explain the work","why":"Redaction should protect sensitive information while retaining a useful explanation where permitted.","correct":true,"id":"C"},{"text":"Remove every axis and measure definition as well as names","why":"Redaction should protect sensitive information while retaining a useful explanation where permitted.","correct":false,"id":"D"},{"text":"Replace confidential names with invented facts and present them as original","why":"Fabricated evidence and an exposed original undermine the purpose of safe redaction.","correct":false,"id":"E"},{"text":"Check that redacted details cannot be recovered from the submitted file","why":"A visual cover may not actually remove the sensitive content.","correct":true,"id":"F"},{"text":"Follow the employer's permission and redaction requirements","why":"The portfolio purpose does not remove the organisation's handling rules.","correct":true,"id":"G"},{"text":"Cover names visually while leaving accessible underlying text","why":"A visual cover may not actually remove the sensitive content.","correct":false,"id":"H"}],"answer":"The portfolio purpose does not remove the organisation's handling rules. A visual cover may not actually remove the sensitive content. Redaction should protect sensitive information while retaining a useful explanation where permitted. Fabricated evidence and an exposed original undermine the purpose of safe redaction.","source":{"anchor":"ksb-s3","guideSha256":"6e7245ee3fe6dc9da12b01ab547600adaa1bbf9400a7ecf58a49c2ba5d8fe83f","excerpt":"Assess sensitivity, identifiability, purpose, access and potential harm, then apply your organisation's real classification and handling scheme."},"id":"T28-E2-Q09"},{"ksb":"S3","objective":"Indirect identifiers","prompt":"A dataset removes names but retains exact dates, rare diagnoses and small locations. Which practical assessment is justified?","options":[{"text":"Assume random record IDs guarantee anonymity","why":"Random identifiers do not remove identifying detail elsewhere in the record.","correct":false,"id":"A"},{"text":"Declare the output risk-free solely after removing names","why":"Redaction of one field does not establish that all identification risk is gone.","correct":false,"id":"B"},{"text":"Check only whether a name column remains","why":"Indirect combinations can identify a person without direct names.","correct":false,"id":"C"},{"text":"Explain remaining risk and controls","why":"Redaction of one field does not establish that all identification risk is gone.","correct":true,"id":"D"},{"text":"Assess the extract without considering possible linkage","why":"Identifiability depends partly on the release context and information recipients can access.","correct":false,"id":"E"},{"text":"Evaluate identification through combinations of fields","why":"Indirect combinations can identify a person without direct names.","correct":true,"id":"F"},{"text":"Consider the intended recipients and available external information","why":"Identifiability depends partly on the release context and information recipients can access.","correct":true,"id":"G"},{"text":"Apply justified minimisation or aggregation before sharing","why":"Random identifiers do not remove identifying detail elsewhere in the record.","correct":true,"id":"H"}],"answer":"Indirect combinations can identify a person without direct names. Identifiability depends partly on the release context and information recipients can access. Random identifiers do not remove identifying detail elsewhere in the record. Redaction of one field does not establish that all identification risk is gone.","source":{"anchor":"ksb-s3","guideSha256":"6e7245ee3fe6dc9da12b01ab547600adaa1bbf9400a7ecf58a49c2ba5d8fe83f","excerpt":"Assess sensitivity, identifiability, purpose, access and potential harm, then apply your organisation's real classification and handling scheme."},"id":"T28-E2-Q10"}]},{"id":"T29","title":"S4 · Analysing Diverse Data Structures & Designs","description":"Actual shape, grain, relationships and adaptations across structures.","questions":[{"ksb":"S4","objective":"Event versus entity","prompt":"One file records each status change; another records one current row per case. Which preparation choices respect the different designs?","options":[{"text":"Define whether the analysis needs events or cases","why":"Combining different grains without treatment can overcount the case population.","correct":true,"id":"A"},{"text":"Stack both files and count all rows as cases","why":"Combining different grains without treatment can overcount the case population.","correct":false,"id":"B"},{"text":"Expect event count to equal case count","why":"A case can have several events, so those counts have different meanings.","correct":false,"id":"C"},{"text":"Treat the first exported event as the final status","why":"Export position does not necessarily establish event chronology or current state.","correct":false,"id":"D"},{"text":"Order events using appropriate timestamps and tie rules","why":"Export position does not necessarily establish event chronology or current state.","correct":true,"id":"E"},{"text":"Reconcile a derived case summary with the current-state source where appropriate","why":"A case can have several events, so those counts have different meanings.","correct":true,"id":"F"},{"text":"Infer missing cases solely because event totals exceed case totals","why":"Repetition at event grain is expected and needs context rather than automatic deletion.","correct":false,"id":"G"},{"text":"Delete repeated case IDs before deciding which event is relevant","why":"Repetition at event grain is expected and needs context rather than automatic deletion.","correct":false,"id":"H"}],"answer":"Combining different grains without treatment can overcount the case population. Export position does not necessarily establish event chronology or current state. A case can have several events, so those counts have different meanings. Repetition at event grain is expected and needs context rather than automatic deletion.","source":{"anchor":"ksb-s4","guideSha256":"6467e74ee7d9e4c6b7f7cc7ae81972bb70699e72444b1b7ff0df47f9d8a010a4","excerpt":"State the shape, grain, schema, keys and field types of each actual dataset, including row and column counts at the relevant extraction date."},"id":"T29-E2-Q01"},{"ksb":"S4","objective":"Schema drift","prompt":"A supplier changes amount from a numeric field to strings with currency symbols. Which adaptation is appropriate?","options":[{"text":"Treat the new type as evidence all historical values are invalid","why":"Neither a type change nor a stable name settles the accuracy and meaning of all values.","correct":false,"id":"A"},{"text":"Disable type checks permanently to allow future changes","why":"A controlled schema update preserves useful validation.","correct":false,"id":"B"},{"text":"Accept any conversion that produces a numeric column","why":"A numeric output can still misrepresent the original amounts.","correct":false,"id":"C"},{"text":"Assume identical column names guarantee unchanged contents","why":"Neither a type change nor a stable name settles the accuracy and meaning of all values.","correct":false,"id":"D"},{"text":"Validate transformed values and rejected entries","why":"A numeric output can still misrepresent the original amounts.","correct":true,"id":"E"},{"text":"Update the expected schema and relevant checks","why":"A controlled schema update preserves useful validation.","correct":true,"id":"F"},{"text":"Parse the documented representation and confirm units","why":"Naive stripping can alter negatives, decimals or currency meaning.","correct":true,"id":"G"},{"text":"Strip every non-digit character without considering decimal signs","why":"Naive stripping can alter negatives, decimals or currency meaning.","correct":false,"id":"H"}],"answer":"Naive stripping can alter negatives, decimals or currency meaning. A numeric output can still misrepresent the original amounts. A controlled schema update preserves useful validation. Neither a type change nor a stable name settles the accuracy and meaning of all values.","source":{"anchor":"ksb-s4","guideSha256":"6467e74ee7d9e4c6b7f7cc7ae81972bb70699e72444b1b7ff0df47f9d8a010a4","excerpt":"State the shape, grain, schema, keys and field types of each actual dataset, including row and column counts at the relevant extraction date."},"id":"T29-E2-Q02"},{"ksb":"S4","objective":"Design trade-offs","prompt":"A denormalised reporting table repeats descriptive attributes to simplify common queries. Which explanation is balanced?","options":[{"text":"Claim normalisation is always unsuitable for reporting","why":"Design choices have contextual trade-offs rather than universal performance guarantees.","correct":false,"id":"A"},{"text":"Repeated attributes always prove the design is erroneous","why":"Denormalisation can be a justified analytical design choice.","correct":false,"id":"B"},{"text":"Claim denormalisation makes every query faster without measurement","why":"Design choices have contextual trade-offs rather than universal performance guarantees.","correct":false,"id":"C"},{"text":"Consider consistency and maintenance of repeated attributes","why":"Repeated information needs suitable maintenance and consistency controls.","correct":true,"id":"D"},{"text":"Simpler consumption can be a deliberate reporting benefit","why":"Denormalisation can be a justified analytical design choice.","correct":true,"id":"E"},{"text":"Assume repetition eliminates update anomalies","why":"Repeated information needs suitable maintenance and consistency controls.","correct":false,"id":"F"},{"text":"Describe every reporting table as the operational master source","why":"A reporting representation may be derived from separate operational records.","correct":false,"id":"G"},{"text":"Explain the actual role of the table in the architecture","why":"A reporting representation may be derived from separate operational records.","correct":true,"id":"H"}],"answer":"Denormalisation can be a justified analytical design choice. Repeated information needs suitable maintenance and consistency controls. A reporting representation may be derived from separate operational records. Design choices have contextual trade-offs rather than universal performance guarantees.","source":{"anchor":"ksb-s4","guideSha256":"6467e74ee7d9e4c6b7f7cc7ae81972bb70699e72444b1b7ff0df47f9d8a010a4","excerpt":"State the shape, grain, schema, keys and field types of each actual dataset, including row and column counts at the relevant extraction date."},"id":"T29-E2-Q03"},{"ksb":"S4","objective":"Grain and dimensions","prompt":"An extract has 1,200 rows and eight columns, with one row per order line. Which description supports analysis?","options":[{"text":"State the extraction point and row/column counts","why":"Counts refer to a particular extract and can change as the source changes.","correct":true,"id":"A"},{"text":"Describe the counts as permanent properties of the source system","why":"Counts refer to a particular extract and can change as the source changes.","correct":false,"id":"B"},{"text":"Treat eight columns as proof of eight independent datasets","why":"Repeated parent IDs can be valid, and fields do not each constitute separate datasets.","correct":false,"id":"C"},{"text":"Call every row a distinct customer","why":"The stated analytical unit is not the customer entity.","correct":false,"id":"D"},{"text":"Describe the structure only by its file size","why":"Shape and meaning need more than a byte count.","correct":false,"id":"E"},{"text":"Explain that the grain is an order line","why":"The stated analytical unit is not the customer entity.","correct":true,"id":"F"},{"text":"Identify relevant keys, types and relationships","why":"Shape and meaning need more than a byte count.","correct":true,"id":"G"},{"text":"Deduplicate all repeated order IDs before checking line meaning","why":"Repeated parent IDs can be valid, and fields do not each constitute separate datasets.","correct":false,"id":"H"}],"answer":"Counts refer to a particular extract and can change as the source changes. The stated analytical unit is not the customer entity. Shape and meaning need more than a byte count. Repeated parent IDs can be valid, and fields do not each constitute separate datasets.","source":{"anchor":"ksb-s4","guideSha256":"6467e74ee7d9e4c6b7f7cc7ae81972bb70699e72444b1b7ff0df47f9d8a010a4","excerpt":"State the shape, grain, schema, keys and field types of each actual dataset, including row and column counts at the relevant extraction date."},"id":"T29-E2-Q04"},{"ksb":"S4","objective":"Relational strengths","prompt":"An analysis draws on related customers, orders and products tables. Which RDBMS features are relevant?","options":[{"text":"Constraints can prevent certain invalid states","why":"Constraints enforce defined rules but cannot establish every fact's real-world truth.","correct":true,"id":"A"},{"text":"Querying tables automatically proves you designed the database","why":"Using an existing design is different from personally creating it.","correct":false,"id":"B"},{"text":"Assume relational design removes every schema-change cost","why":"Query performance and controlled schema changes remain practical trade-offs.","correct":false,"id":"C"},{"text":"Constraints prove that every real-world value is accurate","why":"Constraints enforce defined rules but cannot establish every fact's real-world truth.","correct":false,"id":"D"},{"text":"Every entity must be repeated in full on every order row","why":"Relationships can avoid unnecessary repetition of shared entity attributes.","correct":false,"id":"E"},{"text":"Assume every join is cheap regardless of data volume and indexes","why":"Query performance and controlled schema changes remain practical trade-offs.","correct":false,"id":"F"},{"text":"SQL can combine and summarise related tables","why":"Using an existing design is different from personally creating it.","correct":true,"id":"G"},{"text":"Keys and relationships organise linked entities","why":"Relationships can avoid unnecessary repetition of shared entity attributes.","correct":true,"id":"H"}],"answer":"Relationships can avoid unnecessary repetition of shared entity attributes. Constraints enforce defined rules but cannot establish every fact's real-world truth. Using an existing design is different from personally creating it. Query performance and controlled schema changes remain practical trade-offs.","source":{"anchor":"ksb-s4","guideSha256":"6467e74ee7d9e4c6b7f7cc7ae81972bb70699e72444b1b7ff0df47f9d8a010a4","excerpt":"State the shape, grain, schema, keys and field types of each actual dataset, including row and column counts at the relevant extraction date."},"id":"T29-E2-Q05"},{"ksb":"S4","objective":"Relationship cardinality","prompt":"One department has many staff records. A report joins department attributes to staff. Which interpretation is correct?","options":[{"text":"Assume a relational source guarantees the join used the right keys","why":"A well-designed source does not prevent an analyst from choosing an inappropriate join.","correct":false,"id":"A"},{"text":"Repeated department IDs can be valid in staff rows","why":"A one-to-many relationship legitimately repeats the parent identifier on the child side.","correct":true,"id":"B"},{"text":"Department ID must be unique on both sides of every join","why":"A one-to-many relationship legitimately repeats the parent identifier on the child side.","correct":false,"id":"C"},{"text":"Use joined staff row count as the number of departments","why":"Distinct entities require counts aligned to their own identifiers.","correct":false,"id":"D"},{"text":"Explain the effect of the join on analytical totals","why":"A well-designed source does not prevent an analyst from choosing an inappropriate join.","correct":true,"id":"E"},{"text":"Check the department lookup's uniqueness","why":"The reference side needs a justified unique meaning or an explicitly handled multiplicity.","correct":true,"id":"F"},{"text":"Select the first conflicting department record without investigation","why":"The reference side needs a justified unique meaning or an explicitly handled multiplicity.","correct":false,"id":"G"},{"text":"Count staff and departments at their respective grains","why":"Distinct entities require counts aligned to their own identifiers.","correct":true,"id":"H"}],"answer":"A one-to-many relationship legitimately repeats the parent identifier on the child side. The reference side needs a justified unique meaning or an explicitly handled multiplicity. Distinct entities require counts aligned to their own identifiers. A well-designed source does not prevent an analyst from choosing an inappropriate join.","source":{"anchor":"ksb-s4","guideSha256":"6467e74ee7d9e4c6b7f7cc7ae81972bb70699e72444b1b7ff0df47f9d8a010a4","excerpt":"State the shape, grain, schema, keys and field types of each actual dataset, including row and column counts at the relevant extraction date."},"id":"T29-E2-Q06"},{"ksb":"S4","objective":"Documenting adaptation","prompt":"You flatten JSON, code comments and join relational reference data. Which evidence shows that you adapted analysis to structure?","options":[{"text":"Apply identical cleaning steps to every source without considering meaning","why":"Different structures can require different justified preparation.","correct":false,"id":"A"},{"text":"Claim authorship of the database because you queried its tables","why":"Analysing a structure does not imply designing the underlying system.","correct":false,"id":"B"},{"text":"Show checks that entities and important totals were preserved","why":"Import success does not establish that reshaping preserved the intended information.","correct":true,"id":"C"},{"text":"Treat successful import as the only validation","why":"Import success does not establish that reshaping preserved the intended information.","correct":false,"id":"D"},{"text":"Distinguish your adaptation from the source system's original design","why":"Analysing a structure does not imply designing the underlying system.","correct":true,"id":"E"},{"text":"Explain why each transformation served the analytical question","why":"Different structures can require different justified preparation.","correct":true,"id":"F"},{"text":"List file extensions without explaining transformations","why":"Structure matters through analytical units and transformations, not only extension names.","correct":false,"id":"G"},{"text":"Describe the original and resulting grains","why":"Structure matters through analytical units and transformations, not only extension names.","correct":true,"id":"H"}],"answer":"Structure matters through analytical units and transformations, not only extension names. Import success does not establish that reshaping preserved the intended information. Different structures can require different justified preparation. Analysing a structure does not imply designing the underlying system.","source":{"anchor":"ksb-s4","guideSha256":"6467e74ee7d9e4c6b7f7cc7ae81972bb70699e72444b1b7ff0df47f9d8a010a4","excerpt":"State the shape, grain, schema, keys and field types of each actual dataset, including row and column counts at the relevant extraction date."},"id":"T29-E2-Q07"},{"ksb":"S4","objective":"Nested expansion","prompt":"Three customer records contain order arrays of lengths 2, 0 and 3. You create one row per actual order, without placeholder rows. Which results and checks follow?","options":[{"text":"All three customers necessarily appear in this order-only table","why":"The customer with no orders has no row when placeholders are excluded.","correct":false,"id":"A"},{"text":"It contains six rows because the empty array creates an actual order","why":"The stated expansion retains actual orders only, so 2 + 0 + 3 gives five.","correct":false,"id":"B"},{"text":"Two customer IDs appear in the order rows","why":"The customer with no orders has no row when placeholders are excluded.","correct":true,"id":"C"},{"text":"Expect the table to keep the original three-row count","why":"Expansion changes the grain from customer objects to orders.","correct":false,"id":"D"},{"text":"Compare expanded counts with the source arrays","why":"Expansion changes the grain from customer objects to orders.","correct":true,"id":"E"},{"text":"Drop the customer key because expansion makes relationships unnecessary","why":"The key preserves which customer each expanded order belongs to.","correct":false,"id":"F"},{"text":"The expanded table contains five order rows","why":"The stated expansion retains actual orders only, so 2 + 0 + 3 gives five.","correct":true,"id":"G"},{"text":"Retain the customer key on each order row","why":"The key preserves which customer each expanded order belongs to.","correct":true,"id":"H"}],"answer":"The stated expansion retains actual orders only, so 2 + 0 + 3 gives five. The customer with no orders has no row when placeholders are excluded. The key preserves which customer each expanded order belongs to. Expansion changes the grain from customer objects to orders.","source":{"anchor":"ksb-s4","guideSha256":"6467e74ee7d9e4c6b7f7cc7ae81972bb70699e72444b1b7ff0df47f9d8a010a4","excerpt":"State the shape, grain, schema, keys and field types of each actual dataset, including row and column counts at the relevant extraction date."},"id":"T29-E2-Q08"},{"ksb":"S4","objective":"Text and tabular inputs","prompt":"A project compares numeric waiting times with free-text feedback. Which adaptations are justified?","options":[{"text":"Claim converting text to counts removes interpretation bias","why":"Coding can introduce uncertainty and bias that should remain visible.","correct":false,"id":"A"},{"text":"Apply a documented coding process to narrative feedback","why":"Word counts may support exploration, but synonyms, negation and context need meaningful, consistent coding rules when identifying themes.","correct":true,"id":"B"},{"text":"Average arbitrary numbers assigned to feedback themes as satisfaction","why":"Theme codes do not become a quantitative satisfaction scale merely by being numeric.","correct":false,"id":"C"},{"text":"Use exact word counts as a complete substitute for interpreting the comments' themes","why":"Word counts may support exploration, but synonyms, negation and context need meaningful, consistent coding rules when identifying themes.","correct":false,"id":"D"},{"text":"Explain how the two sources relate in population and time","why":"A meaningful relationship needs a justified design or key, not arbitrary proximity.","correct":true,"id":"E"},{"text":"Use suitable numerical summaries for durations","why":"Theme codes do not become a quantitative satisfaction scale merely by being numeric.","correct":true,"id":"F"},{"text":"Retain limitations of the qualitative interpretation","why":"Coding can introduce uncertainty and bias that should remain visible.","correct":true,"id":"G"},{"text":"Join unrelated comments to whichever duration is closest","why":"A meaningful relationship needs a justified design or key, not arbitrary proximity.","correct":false,"id":"H"}],"answer":"Theme codes do not become a quantitative satisfaction scale merely by being numeric. Word counts may support exploration, but synonyms, negation and context need meaningful, consistent coding rules when identifying themes. A meaningful relationship needs a justified design or key, not arbitrary proximity. Coding can introduce uncertainty and bias that should remain visible.","source":{"anchor":"ksb-s4","guideSha256":"6467e74ee7d9e4c6b7f7cc7ae81972bb70699e72444b1b7ff0df47f9d8a010a4","excerpt":"State the shape, grain, schema, keys and field types of each actual dataset, including row and column counts at the relevant extraction date."},"id":"T29-E2-Q09"},{"ksb":"S4","objective":"Wide to long","prompt":"A table has one row per service and twelve columns named for months. You need monthly comparisons across services. Which transformation is appropriate?","options":[{"text":"Retain the service identifier on resulting rows","why":"The intended service-month grain requires both dimensions.","correct":true,"id":"A"},{"text":"Treat a larger row count as proof that totals increased","why":"Reshaping can increase rows without increasing the underlying amounts.","correct":false,"id":"B"},{"text":"Check missing and non-numeric month values explicitly","why":"Empty values may reflect missing observations rather than observed zero activity.","correct":true,"id":"C"},{"text":"Unpivot month columns into a month field and value field","why":"Unpivoting preserves the actual monthly values rather than inventing equal monthly allocations.","correct":true,"id":"D"},{"text":"Convert every empty month cell to zero without checking meaning","why":"Empty values may reflect missing observations rather than observed zero activity.","correct":false,"id":"E"},{"text":"Remove service IDs because month now identifies every row","why":"The intended service-month grain requires both dimensions.","correct":false,"id":"F"},{"text":"Duplicate each annual total into twelve monthly rows","why":"Unpivoting preserves the actual monthly values rather than inventing equal monthly allocations.","correct":false,"id":"G"},{"text":"Reconcile totals before and after reshaping","why":"Reshaping can increase rows without increasing the underlying amounts.","correct":true,"id":"H"}],"answer":"Unpivoting preserves the actual monthly values rather than inventing equal monthly allocations. The intended service-month grain requires both dimensions. Reshaping can increase rows without increasing the underlying amounts. Empty values may reflect missing observations rather than observed zero activity.","source":{"anchor":"ksb-s4","guideSha256":"6467e74ee7d9e4c6b7f7cc7ae81972bb70699e72444b1b7ff0df47f9d8a010a4","excerpt":"State the shape, grain, schema, keys and field types of each actual dataset, including row and column counts at the relevant extraction date."},"id":"T29-E2-Q10"}]},{"id":"T30","title":"S5 · Applying UX & Domain Context","description":"Practical visual hierarchy, domain rules, accessibility and user feedback.","questions":[{"ksb":"S5","objective":"Empty and stale states","prompt":"A dashboard may have no matching records or an overdue refresh. Which UX behaviour is appropriate?","options":[{"text":"Display the current clock time as the data timestamp","why":"The time shown should describe the data or refresh accurately.","correct":false,"id":"A"},{"text":"Distinguish no matches from a genuine zero result","why":"A failed load or empty selection does not necessarily mean zero activity.","correct":true,"id":"B"},{"text":"Show a relevant data currency or refresh warning","why":"The time shown should describe the data or refresh accurately.","correct":true,"id":"C"},{"text":"Explain a useful next action for the user","why":"Clear state information helps users understand and recover from the condition.","correct":true,"id":"D"},{"text":"Preserve yesterday's values under an unqualified current-data heading","why":"A clean appearance should not conceal material uncertainty about what the figures represent.","correct":false,"id":"E"},{"text":"Hide all warnings to keep the dashboard visually clean","why":"A clean appearance should not conceal material uncertainty about what the figures represent.","correct":false,"id":"F"},{"text":"Display zero for every failed data load","why":"A failed load or empty selection does not necessarily mean zero activity.","correct":false,"id":"G"},{"text":"Leave an unexplained blank panel","why":"Clear state information helps users understand and recover from the condition.","correct":false,"id":"H"}],"answer":"A failed load or empty selection does not necessarily mean zero activity. The time shown should describe the data or refresh accurately. Clear state information helps users understand and recover from the condition. A clean appearance should not conceal material uncertainty about what the figures represent.","source":{"anchor":"ksb-s5","guideSha256":"ae3dee68ad2f3e625ff15c4d92fe7dea8079d619397bfe07497e53d6af6fe64a","excerpt":"Connect each design choice to a stakeholder task."},"id":"T30-E2-Q01"},{"ksb":"S5","objective":"Working-day calculation","prompt":"Stakeholders assess a working-day service target. Your prototype uses calendar days. Which actions apply domain context to the output?","options":[{"text":"Change the chart label without recalculating","why":"The displayed definition must match the actual values.","correct":false,"id":"A"},{"text":"Present both units against the same threshold without explanation","why":"The output must implement the agreed working-day definition. A new label alone does not change the underlying calculation.","correct":false,"id":"B"},{"text":"Confirm the working-day and holiday rules","why":"Individual intervals and applicable holidays can differ.","correct":true,"id":"C"},{"text":"Assume every seven calendar days equals five working days for each interval","why":"Individual intervals and applicable holidays can differ.","correct":false,"id":"D"},{"text":"Explain the measure beside the visual","why":"Explicit units and definitions reduce ambiguity, especially for shared or exported views.","correct":true,"id":"E"},{"text":"Omit the unit because regular users know the service","why":"Explicit units and definitions reduce ambiguity, especially for shared or exported views.","correct":false,"id":"F"},{"text":"Relabel calendar-day values as working days without recalculating them","why":"The output must implement the agreed working-day definition. A new label alone does not change the underlying calculation.","correct":false,"id":"G"},{"text":"Implement and validate the agreed calculation","why":"The displayed definition must match the actual values.","correct":true,"id":"H"}],"answer":"Individual intervals and applicable holidays can differ. The displayed definition must match the actual values. Explicit units and definitions reduce ambiguity, especially for shared or exported views. The output must implement the agreed working-day definition. A new label alone does not change the underlying calculation.","source":{"anchor":"ksb-s5","guideSha256":"ae3dee68ad2f3e625ff15c4d92fe7dea8079d619397bfe07497e53d6af6fe64a","excerpt":"Connect each design choice to a stakeholder task."},"id":"T30-E2-Q02"},{"ksb":"S5","objective":"Domain comparability","prompt":"Two teams handle different case complexity. Your dashboard ranks them by average duration. Which applied changes are defensible?","options":[{"text":"Treat agreement on the ranking format as confirmation that complexity differences have been controlled","why":"Users can accept a presentation while the comparison remains confounded; domain meaning and case-mix validity need separate review.","correct":false,"id":"A"},{"text":"Present the ranking as a direct measure of staff effort","why":"Duration can reflect case complexity and other factors besides effort.","correct":false,"id":"B"},{"text":"Invent an adjustment factor that makes teams appear equal","why":"A correction needs a defensible basis rather than a desired visual outcome.","correct":false,"id":"C"},{"text":"Truncate axes solely to make small differences look dramatic","why":"Chart design should aid interpretation rather than exaggerate it.","correct":false,"id":"D"},{"text":"Validate the revised measure and explanation with stakeholders","why":"Users can accept a presentation while the comparison remains confounded; domain meaning and case-mix validity need separate review.","correct":true,"id":"E"},{"text":"Choose a representation that supports the agreed comparison","why":"Chart design should aid interpretation rather than exaggerate it.","correct":true,"id":"F"},{"text":"Explore suitable stratification or context with domain owners","why":"A correction needs a defensible basis rather than a desired visual outcome.","correct":true,"id":"G"},{"text":"Explain the case-mix limitation near the ranking","why":"Duration can reflect case complexity and other factors besides effort.","correct":true,"id":"H"}],"answer":"Duration can reflect case complexity and other factors besides effort. A correction needs a defensible basis rather than a desired visual outcome. Chart design should aid interpretation rather than exaggerate it. Users can accept a presentation while the comparison remains confounded; domain meaning and case-mix validity need separate review.","source":{"anchor":"ksb-s5","guideSha256":"ae3dee68ad2f3e625ff15c4d92fe7dea8079d619397bfe07497e53d6af6fe64a","excerpt":"Connect each design choice to a stakeholder task."},"id":"T30-E2-Q03"},{"ksb":"S5","objective":"Colour and labels","prompt":"Your dashboard distinguishes overdue and on-time cases only by red and green. Which practical changes improve interpretation?","options":[{"text":"Infer keyboard usability from successful mouse interaction","why":"Different interaction methods require practical checks of their behaviour.","correct":false,"id":"A"},{"text":"Test the relevant controls with a keyboard","why":"Different interaction methods require practical checks of their behaviour.","correct":true,"id":"B"},{"text":"Preserve the status meaning in exported views","why":"Exported information still needs its interpretation context.","correct":true,"id":"C"},{"text":"Assume a bright palette guarantees readable contrast","why":"Contrast needs to be assessed in the actual combinations used.","correct":false,"id":"D"},{"text":"Add explicit status labels or other non-colour cues","why":"Additional cues support users who cannot reliably distinguish the colours.","correct":true,"id":"E"},{"text":"Change to two different shades without another identifier","why":"Additional cues support users who cannot reliably distinguish the colours.","correct":false,"id":"F"},{"text":"Put the legend only in a panel excluded from exports","why":"Exported information still needs its interpretation context.","correct":false,"id":"G"},{"text":"Check text and indicator contrast on their backgrounds","why":"Contrast needs to be assessed in the actual combinations used.","correct":true,"id":"H"}],"answer":"Additional cues support users who cannot reliably distinguish the colours. Contrast needs to be assessed in the actual combinations used. Exported information still needs its interpretation context. Different interaction methods require practical checks of their behaviour.","source":{"anchor":"ksb-s5","guideSha256":"ae3dee68ad2f3e625ff15c4d92fe7dea8079d619397bfe07497e53d6af6fe64a","excerpt":"Connect each design choice to a stakeholder task."},"id":"T30-E2-Q04"},{"ksb":"S5","objective":"Evidence of design choices","prompt":"Your portfolio includes a dashboard screenshot. Which accompanying explanation demonstrates S5 more convincingly?","options":[{"text":"Attribute invented usability comments to unnamed users","why":"Evidence needs to be truthful and connected to the design decisions made.","correct":false,"id":"A"},{"text":"Describe the layout only as modern and professional","why":"A concrete task explains why the design choices were useful.","correct":false,"id":"B"},{"text":"Reference genuine feedback and any resulting changes","why":"Evidence needs to be truthful and connected to the design decisions made.","correct":true,"id":"C"},{"text":"Claim domain context from the organisation's logo alone","why":"Domain application concerns the meaning and constraints of the analysis, not branding alone.","correct":false,"id":"D"},{"text":"Describe accessibility checks actually performed","why":"A claim should be bounded by the checks and behaviour actually evaluated.","correct":true,"id":"E"},{"text":"Explain an actual domain rule used in a calculation or interpretation","why":"Domain application concerns the meaning and constraints of the analysis, not branding alone.","correct":true,"id":"F"},{"text":"Link layout choices to a stakeholder's task","why":"A concrete task explains why the design choices were useful.","correct":true,"id":"G"},{"text":"Claim complete conformance solely because a template was used","why":"A claim should be bounded by the checks and behaviour actually evaluated.","correct":false,"id":"H"}],"answer":"A concrete task explains why the design choices were useful. Domain application concerns the meaning and constraints of the analysis, not branding alone. A claim should be bounded by the checks and behaviour actually evaluated. Evidence needs to be truthful and connected to the design decisions made.","source":{"anchor":"ksb-s5","guideSha256":"ae3dee68ad2f3e625ff15c4d92fe7dea8079d619397bfe07497e53d6af6fe64a","excerpt":"Connect each design choice to a stakeholder task."},"id":"T30-E2-Q05"},{"ksb":"S5","objective":"Accessible alternatives","prompt":"A chart is useful visually but its meaning is unavailable to a screen-reader user. Which improvements are appropriate?","options":[{"text":"Check the actual tool's accessibility behaviour","why":"Accessibility depends on the implementation and platform behaviour used.","correct":true,"id":"A"},{"text":"Offer an accessible table where exact values matter","why":"A table alternative needs to make its structure and values accessible, not merely display another image.","correct":true,"id":"B"},{"text":"Rely on colour and position alone to name controls","why":"Meaningful labels and focus support users who cannot rely on visual position.","correct":false,"id":"C"},{"text":"Use 'chart image' as the only description","why":"A generic label does not convey the relevant information.","correct":false,"id":"D"},{"text":"Provide a meaningful description of the key comparison","why":"A generic label does not convey the relevant information.","correct":true,"id":"E"},{"text":"Provide an image of the table as the only alternative","why":"A table alternative needs to make its structure and values accessible, not merely display another image.","correct":false,"id":"F"},{"text":"Give interactive controls meaningful labels and focus behaviour","why":"Meaningful labels and focus support users who cannot rely on visual position.","correct":true,"id":"G"},{"text":"Assume all dashboards inherit identical accessibility from their vendor","why":"Accessibility depends on the implementation and platform behaviour used.","correct":false,"id":"H"}],"answer":"A generic label does not convey the relevant information. A table alternative needs to make its structure and values accessible, not merely display another image. Meaningful labels and focus support users who cannot rely on visual position. Accessibility depends on the implementation and platform behaviour used.","source":{"anchor":"ksb-s5","guideSha256":"ae3dee68ad2f3e625ff15c4d92fe7dea8079d619397bfe07497e53d6af6fe64a","excerpt":"Connect each design choice to a stakeholder task."},"id":"T30-E2-Q06"},{"ksb":"S5","objective":"Visible filter context","prompt":"A filtered dashboard is regularly shared as screenshots. Which design choices prevent readers mistaking a subset for the whole service?","options":[{"text":"Reset labels to organisation-wide while keeping filtered numbers","why":"Removing context can make a subset look like an organisation-wide result.","correct":false,"id":"A"},{"text":"Hide filter state to make the screenshot less cluttered","why":"Removing context can make a subset look like an organisation-wide result.","correct":false,"id":"B"},{"text":"Display active population filters in the captured view","why":"The current subset needs explicit context.","correct":true,"id":"C"},{"text":"Put all context in hover-only elements that disappear in screenshots","why":"Static exports cannot preserve information available only through interaction.","correct":false,"id":"D"},{"text":"Show the period represented by the values","why":"A screenshot's creation date and the observations' reporting period are different; readers need the actual period represented.","correct":true,"id":"E"},{"text":"Label the capture date as the reporting period even when the data covers an earlier window","why":"A screenshot's creation date and the observations' reporting period are different; readers need the actual period represented.","correct":false,"id":"F"},{"text":"Assume the report title alone describes every filter combination","why":"The current subset needs explicit context.","correct":false,"id":"G"},{"text":"Keep essential definitions with the exported chart","why":"Static exports cannot preserve information available only through interaction.","correct":true,"id":"H"}],"answer":"The current subset needs explicit context. A screenshot's creation date and the observations' reporting period are different; readers need the actual period represented. Static exports cannot preserve information available only through interaction. Removing context can make a subset look like an organisation-wide result.","source":{"anchor":"ksb-s5","guideSha256":"ae3dee68ad2f3e625ff15c4d92fe7dea8079d619397bfe07497e53d6af6fe64a","excerpt":"Connect each design choice to a stakeholder task."},"id":"T30-E2-Q07"},{"ksb":"S5","objective":"Applying hierarchy","prompt":"Users miss a dashboard's important exception because every card looks equally prominent. Which implementation choices address the observed problem?","options":[{"text":"Declare success solely because the designer prefers the new layout","why":"Task-based feedback checks the actual usability problem.","correct":false,"id":"A"},{"text":"Hide the measure until users open several unrelated panels","why":"A simpler implementation or extra navigation does not meet the stated decision need.","correct":false,"id":"B"},{"text":"Give every supporting metric the same visual weight as the actionable exception","why":"Supporting information should help interpret the decision-critical exception without competing equally for attention.","correct":false,"id":"C"},{"text":"Make every card equally larger","why":"Equal enlargement does not resolve the lack of hierarchy.","correct":false,"id":"D"},{"text":"Group supporting detail beneath the decision-critical measure","why":"Supporting information should help interpret the decision-critical exception without competing equally for attention.","correct":true,"id":"E"},{"text":"Replace the exception with the easiest metric to calculate","why":"A simpler implementation or extra navigation does not meet the stated decision need.","correct":false,"id":"F"},{"text":"Give the exception clear visual priority and context","why":"Equal enlargement does not resolve the lack of hierarchy.","correct":true,"id":"G"},{"text":"Retest whether users can identify the exception","why":"Task-based feedback checks the actual usability problem.","correct":true,"id":"H"}],"answer":"Equal enlargement does not resolve the lack of hierarchy. Supporting information should help interpret the decision-critical exception without competing equally for attention. Task-based feedback checks the actual usability problem. A simpler implementation or extra navigation does not meet the stated decision need.","source":{"anchor":"ksb-s5","guideSha256":"ae3dee68ad2f3e625ff15c4d92fe7dea8079d619397bfe07497e53d6af6fe64a","excerpt":"Connect each design choice to a stakeholder task."},"id":"T30-E2-Q08"},{"ksb":"S5","objective":"Designing for a decision","prompt":"An executive needs a short service overview; an analyst needs record-level investigation within approved access. Which output design is justified?","options":[{"text":"Apply access controls to the detailed view","why":"Different detail levels can have different authorisation requirements.","correct":true,"id":"A"},{"text":"Give both audiences an identical dense notebook without checking needs","why":"Adapting detail should not remove material context needed for the decision.","correct":false,"id":"B"},{"text":"Omit limitations from the executive view to shorten it","why":"Adapting detail should not remove material context needed for the decision.","correct":false,"id":"C"},{"text":"Change denominators silently between the views","why":"Users need a coherent relationship between the levels of information.","correct":false,"id":"D"},{"text":"Force every user through a large raw table first","why":"The starting view should fit the audience's immediate task.","correct":false,"id":"E"},{"text":"Keep definitions consistent between overview and detail","why":"Users need a coherent relationship between the levels of information.","correct":true,"id":"F"},{"text":"Provide a concise overview with an appropriate route to detail","why":"The starting view should fit the audience's immediate task.","correct":true,"id":"G"},{"text":"Assume permission for aggregate results includes individual records","why":"Different detail levels can have different authorisation requirements.","correct":false,"id":"H"}],"answer":"The starting view should fit the audience's immediate task. Users need a coherent relationship between the levels of information. Different detail levels can have different authorisation requirements. Adapting detail should not remove material context needed for the decision.","source":{"anchor":"ksb-s5","guideSha256":"ae3dee68ad2f3e625ff15c4d92fe7dea8079d619397bfe07497e53d6af6fe64a","excerpt":"Connect each design choice to a stakeholder task."},"id":"T30-E2-Q09"},{"ksb":"S5","objective":"Feedback-driven redesign","prompt":"Two users interpret your cumulative line as monthly activity. Which response demonstrates applied UX?","options":[{"text":"Invent positive feedback to close the review","why":"The account should retain genuine observations and what changed because of them.","correct":false,"id":"A"},{"text":"Document the feedback and the resulting design decision","why":"The account should retain genuine observations and what changed because of them.","correct":true,"id":"B"},{"text":"Ask users to interpret the revised output","why":"Actual interpretation provides stronger evidence than edit volume.","correct":true,"id":"C"},{"text":"Count the number of edits as evidence of usability improvement","why":"Actual interpretation provides stronger evidence than edit volume.","correct":false,"id":"D"},{"text":"Retain the title because the underlying formula is correct","why":"A correct formula can still be communicated misleadingly.","correct":false,"id":"E"},{"text":"Select a new chart solely because it is less familiar","why":"The change should address the interpretation task, not novelty.","correct":false,"id":"F"},{"text":"Clarify the accumulation basis in labels and context","why":"A correct formula can still be communicated misleadingly.","correct":true,"id":"G"},{"text":"Consider a visual better suited to the intended comparison","why":"The change should address the interpretation task, not novelty.","correct":true,"id":"H"}],"answer":"A correct formula can still be communicated misleadingly. The change should address the interpretation task, not novelty. Actual interpretation provides stronger evidence than edit volume. The account should retain genuine observations and what changed because of them.","source":{"anchor":"ksb-s5","guideSha256":"ae3dee68ad2f3e625ff15c4d92fe7dea8079d619397bfe07497e53d6af6fe64a","excerpt":"Connect each design choice to a stakeholder task."},"id":"T30-E2-Q10"}]}]);d.revisedPackSha256["revised-2"]="ed32f408fa7f322b18a3b2d541ff718eceb3a05c53b920f394dfeda8be3a51a6";})();
